CREATE OR REPLACE PACKAGE BODY MGPA_AC_IF
IS
	G_MSG		FCPA_ERR.MSG_BINDER ;
	G_NULL_VAL	CONSTANT MAPA_META.STR20%TYPE := MAC_STR.NULL_VAL ;
	G_OFF		CONSTANT MAPA_META.FLG%TYPE := '0' ;
	G_ON		CONSTANT MAPA_META.FLG%TYPE := '1' ;

	TYPE LIST_JNL_KEY_MAP IS TABLE OF MAM_JNL_KEY_MAP%ROWTYPE INDEX BY BINARY_INTEGER ;
	JNL_KEY_MAP_REC LIST_JNL_KEY_MAP ;

	TYPE BP_GRP_REC_TYPE IS RECORD (
		BP_GRP_CD1	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD2	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD3	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD4	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD5	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD6	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD7	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD8	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD9	MAPA_META.BP_GRP_CD%TYPE,
		BP_GRP_CD10	MAPA_META.BP_GRP_CD%TYPE
	) ;
	TYPE LIST_BP_GRP IS TABLE OF BP_GRP_REC_TYPE INDEX BY MAM_BP.BP_CD%TYPE ;
	C_MAX_BP_CNT	CONSTANT BINARY_INTEGER := 10000 ;
	BP_GRP_REC	LIST_BP_GRP ;

	TYPE BP_REC IS RECORD (
		CST_CD		MAPA_META.BP_CD%TYPE,
		SPPL_CD		MAPA_META.BP_CD%TYPE,
		INV_COM_CD	MAPA_META.BP_CD%TYPE
	) ;

	TYPE LIST_DPT_MAP IS TABLE OF MAPA_META.AC_DPT_CD%TYPE INDEX BY MAPA_META.COST_DPT_CD%TYPE ;
	DPT_MAP_REC	LIST_DPT_MAP ;

FUNCTION F_GET_AC_DPT (
	I_DPT	IN  MAPA_META.COST_DPT_CD%TYPE,
	I_DT	IN  MAPA_META.DT%TYPE,
	I_NE_FLG IN MAPA_META.FLG%TYPE DEFAULT '0'
) RETURN MAPA_META.AC_DPT_CD%TYPE
/**************************************************************************
<SYNOPSIS>
	原価部門ＣＤから会計部門ＣＤへの変換処理
<REMARKS>
	原価部門ＣＤに対するMAM_COST_AC_DPT_MAPが存在しない場合は
	原価部門ＣＤを会計部門ＣＤとする。
	対象となる会計部門ＣＤがMAM_AC_DPTに存在しない場合はエラーとする。
<ARGUMENTS>
<IN>	I_DPT
		原価部門ＣＤ
<IN>	I_DT
		適用日
<RETURNVALUE>
	変換した会計部門ＣＤを返す
<HISTORY>
**************************************************************************/
AS
	L_DPT	MAPA_META.AC_DPT_CD%TYPE ;
	L_CNT	NUMBER ;
BEGIN
	IF I_DPT IS NULL THEN
		RETURN I_DPT ;
	END IF ;

	IF DPT_MAP_REC.EXISTS(I_DPT) THEN
		RETURN DPT_MAP_REC(I_DPT) ;
	END IF ;

	SELECT	NVL(MIN(m.AC_DPT_CD), I_DPT)
	INTO	L_DPT
	FROM	MAM_COST_AC_DPT_MAP m
	WHERE	0=0
	AND	m.DPT_CD = I_DPT
	AND	m.ST_DT <= I_DT
	AND	m.END_DT >= I_DT
	;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MAM_AC_DPT m
	WHERE	0=0
	AND	m.AC_DPT_CD = L_DPT
	AND	m.ST_DT <= I_DT
	AND	m.END_DT >= I_DT
	;

	IF L_CNT = 0 THEN
		-- エラーにしない
		IF I_NE_FLG = '1' THEN
			RETURN NULL ;
		END IF ;
		G_MSG := FCPA_ERR.MSG_BINDER(L_DPT, FCPA_DATE_UTIL.F_TO_CHAR(I_DT, FCPA_DATE_UTIL.Y4MD)) ;
		FCPA_ERR.RAISE_APP_ERR('MGBDD0016', G_MSG) ;
	END IF ;

	DPT_MAP_REC(I_DPT) := L_DPT ;

	RETURN L_DPT ;

END F_GET_AC_DPT ;

PROCEDURE P_GET_JNL_KEY_MAP (
	I_AC_SLIP_TYP		IN	MAPA_META.AC_SLIP_TYP%TYPE,
	I_JNL_KEY_COL_TYP	IN	MAPA_META.JNL_KEY_COL_TYP%TYPE,
	O_JNL_KEY_MAP		OUT	MAM_JNL_KEY_MAP%ROWTYPE
	)
/**************************************************************************
<SYNOPSIS>
	引数に対応する仕訳キー対応マスタのレコードを取得
<REMARKS>

<ARGUMENTS>
<IN>	I_AC_SLIP_TYP
		会計伝票区分
<IN>	I_JNL_KEY_COL_TYP
		仕訳キー項目区分
<OUT>	O_JNL_KEY_MAP
		IN条件に対応する仕訳キー対応マスタのレコード
<HISTORY>
**************************************************************************/
IS
BEGIN
	IF JNL_KEY_MAP_REC.COUNT = 0 OR I_AC_SLIP_TYP IS NULL OR I_JNL_KEY_COL_TYP IS NULL THEN
		O_JNL_KEY_MAP := NULL ;
		RETURN ;
	END IF ;

	FOR n IN 1..JNL_KEY_MAP_REC.COUNT LOOP
		IF JNL_KEY_MAP_REC(n).AC_SLIP_TYP <> I_AC_SLIP_TYP THEN
			CONTINUE ;
		END IF ;
		IF JNL_KEY_MAP_REC(n).JNL_KEY_COL_TYP <> I_JNL_KEY_COL_TYP THEN
			CONTINUE ;
		END IF ;
		O_JNL_KEY_MAP := JNL_KEY_MAP_REC(n) ;
		EXIT ;
	END LOOP ;
END P_GET_JNL_KEY_MAP ;

FUNCTION F_GET_BP_GRP (
	I_JNL_BP_REC	IN	BP_REC,
	I_JNL_KEY_MAP	IN	MAM_JNL_KEY_MAP%ROWTYPE,
	I_BP_GRP_TYP	IN	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE
	)
/**************************************************************************
<SYNOPSIS>
	取引先仕訳キー設定項目区分の取引先に対応する取引先分類ＣＤを取得
<REMARKS>

<ARGUMENTS>
<IN>	I_JNL_BP_REC
		会計情報レコードの取引先
<IN>	I_JNL_KEY_MAP
		仕訳キー対応マスタのレコード
<IN>	I_BP_GRP_TYP
		取引先分類仕訳キー設定項目区分
<HISTORY>
**************************************************************************/
RETURN MAPA_META.BP_GRP_CD%TYPE
IS
	C_CST_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.CST_CD ;
	C_SPPL_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.SPPL_CD ;
	C_INV_COM_CD	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.INV_COM_CD ;

	C_BP_GRP_CD1	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD1 ;
	C_BP_GRP_CD2	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD2 ;
	C_BP_GRP_CD3	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD3 ;
	C_BP_GRP_CD4	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD4 ;
	C_BP_GRP_CD5	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD5 ;
	C_BP_GRP_CD6	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD6 ;
	C_BP_GRP_CD7	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD7 ;
	C_BP_GRP_CD8	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD8 ;
	C_BP_GRP_CD9	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD9 ;
	C_BP_GRP_CD10	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BP_GRP_CD10 ;

	L_BP_GRP_REC	BP_GRP_REC_TYPE ;
	L_BP_CD			MAPA_META.BP_CD%TYPE ;
BEGIN
	IF I_JNL_KEY_MAP.BP_JNL_KEY_SET_COL_TYP IS NULL OR I_BP_GRP_TYP IS NULL THEN
		RETURN NULL ;
	END IF ;

	CASE I_JNL_KEY_MAP.BP_JNL_KEY_SET_COL_TYP
		WHEN C_CST_CD THEN
			L_BP_CD := I_JNL_BP_REC.CST_CD ;
		WHEN C_SPPL_CD THEN
			L_BP_CD := I_JNL_BP_REC.SPPL_CD ;
		WHEN C_INV_COM_CD THEN
			L_BP_CD := I_JNL_BP_REC.INV_COM_CD ;
		ELSE
			RETURN NULL ;
	END CASE ;

	IF L_BP_CD IS NULL THEN
		RETURN NULL ;
	ELSIF BP_GRP_REC.EXISTS(L_BP_CD) THEN
		L_BP_GRP_REC := BP_GRP_REC(L_BP_CD) ;
	ELSE
		FOR m IN (
			SELECT	m.BP_GRP_CD1,
				m.BP_GRP_CD2,
				m.BP_GRP_CD3,
				m.BP_GRP_CD4,
				m.BP_GRP_CD5,
				m.BP_GRP_CD6,
				m.BP_GRP_CD7,
				m.BP_GRP_CD8,
				m.BP_GRP_CD9,
				m.BP_GRP_CD10
			FROM	MAM_BP m
			WHERE	0=0
			AND	m.DEL_FLG = G_OFF
			AND	m.BP_CD = L_BP_CD
			)
		LOOP
			BP_GRP_REC(L_BP_CD) := m ;
			L_BP_GRP_REC := m ;
		END LOOP ;
		IF BP_GRP_REC.COUNT > C_MAX_BP_CNT THEN
			BP_GRP_REC.DELETE ;
		END IF ;
	END IF ;

	-- 取引先分類ＣＤを取得
	CASE I_BP_GRP_TYP
		WHEN C_BP_GRP_CD1 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD1 ;
		WHEN C_BP_GRP_CD2 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD2 ;
		WHEN C_BP_GRP_CD3 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD3 ;
		WHEN C_BP_GRP_CD4 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD4 ;
		WHEN C_BP_GRP_CD5 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD5 ;
		WHEN C_BP_GRP_CD6 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD6 ;
		WHEN C_BP_GRP_CD7 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD7 ;
		WHEN C_BP_GRP_CD8 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD8 ;
		WHEN C_BP_GRP_CD9 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD9 ;
		WHEN C_BP_GRP_CD10 THEN
			RETURN L_BP_GRP_REC.BP_GRP_CD10 ;
		ELSE
			RETURN NULL ;
	END CASE ;
END F_GET_BP_GRP ;

PROCEDURE P_SEND_MAIN (
	I_CALC_GRP_CD	IN MAPA_META.CALC_GRP_CD%TYPE,
	I_CALC_NO	IN MAPA_META.CALC_NO%TYPE,
	I_YM		IN MAPA_META.YM%TYPE
)
/**************************************************************************
<SYNOPSIS>
	会計ＩＦの送信メイン処理
<REMARKS>

<ARGUMENTS>
<IN>	I_CALC_GRP_CD
		計算グループＣＤ
<IN>	I_CALC_NO
		原価計算ＮＯ
<IN>	I_YM
		年月
<HISTORY>
**************************************************************************/
