	C_CALC_REC_COMP		CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.COMP ;
	C_CALC_REC_IO		CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.IO ;
	C_CALC_REC_INPT		CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.INPT ;
	C_CALC_REC_SLS		CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.SLS ;
	C_CALC_REC_END_STK	CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.END_STK ;
	C_CALC_REC_END_WIP	CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.END_WIP ;
	C_CALC_REC_INST		CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.INST ;
	C_CALC_REC_ADJ		CONSTANT MGPA_META.CALC_REC_TYP%TYPE := MGC_CALC_REC_TYP.ADJ ;

	C_COST_IO_FFR_PROV	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.FFR_PROV ;
	C_COST_IO_ONR_PROV	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.ONR_PROV ;
	C_COST_IO_STK_IN	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.STK_IN ;
	C_COST_IO_STK_OUT	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.STK_OUT ;
	C_COST_IO_STK_IO	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.STK_IO ;

	C_ASST_PROD		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.CO_PROD ;
	C_ASST_SLS		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.CO_SLS ;
	C_ASST_OTH		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.OTH ;

	C_AC_SLIP_COMP_CST	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.COMP_CST ;
	C_AC_SLIP_SLS_CST	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.SLS_COST ;
	C_AC_SLIP_MFG		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.MFG ;
	C_AC_SLIP_PURC_COST	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.PURC_COST ;
	C_AC_SLIP_PURC		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.PURC ;
	C_AC_SLIP_EOM_STK_PROD	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.EOM_STK_PROD ;
	C_AC_SLIP_EOM_STK_SLS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.EOM_STK_SLS ;
	C_AC_SLIP_INP_WIP_CST	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.INP_WIP_CST ;
	C_AC_SLIP_INPUT		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.INPUT ;
	C_AC_SLIP_IN_ONR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.IN_ONR ;
	C_AC_SLIP_IN_SS		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.IN_SS ;
	C_AC_SLIP_BYPROD	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.BYPROD ;
	C_AC_SLIP_CST_IO_AOD	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.CST_IO_AOD ;
	C_AC_SLIP_ONR_PROV_DIFF	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.ONR_PROV_DIFF ;
	C_AC_SLIP_IN_ONR_DIFF	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE:= MAC_AC_SLIP_TYP.IN_ONR_DIFF ;
