	TYPE	LIST_AC_DPT IS TABLE OF MAM_AC_DPT.AC_DPT_CD%TYPE INDEX BY BINARY_INTEGER ;
	dpt_path	LIST_AC_DPT ;

	C_WG_CD			CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.WG_CD ;
	C_PURC_DPT_CD	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.PURC_DPT_CD ;
	C_AP_DPT_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.AP_DPT_CD ;
	C_SLS_DPT_CD	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.SLS_DPT_CD ;
