	C_GI_DPT_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.GI_DPT_CD ;
	C_GR_DPT_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.GR_DPT_CD ;
	C_BD_DPT_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.BD_DPT_CD ;
	C_SUB_DPT_CD1	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.SUB_DPT_CD1 ;
	C_SUB_DPT_CD2	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.SUB_DPT_CD2 ;
	C_SUB_DPT_CD3	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.SUB_DPT_CD3 ;
	C_LOC_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.LOC_CD ;
	C_STR_LN_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.STR_LN_CD ;
	C_CST_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.CST_CD ;
	C_SPPL_CD		CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.SPPL_CD ;
	C_INV_COM_CD	CONSTANT	MAPA_META.JNL_KEY_SET_COL_TYP%TYPE := MAC_JNL_KEY_SET_COL_TYP.INV_COM_CD ;
