/*************************************************************************/
PROCEDURE P_AC_COST_INSERT
AS
BEGIN
	IF i > 0 THEN
		FORALL t IN 1..i
			INSERT INTO MBT_AC_COST VALUES rec(t) ;
		rec.DELETE ;
		sum_i := sum_i + i ;
		i := 0 ;
	END IF ;
END ;
/*************************************************************************/
/*************************************************************************/
PROCEDURE P_AC_COST_MERGE
AS
BEGIN
	IF i > 0 THEN
		FORALL j IN 1..i
			MERGE INTO MBT_AC_COST t
			USING (
				SELECT
					rec(j).WG_CD			WG_CD,
					rec(j).AC_YM			AC_YM,
					rec(j).CALC_GRP_CD		CALC_GRP_CD,
					rec(j).CALC_NO			CALC_NO,
					rec(j).AC_DT			AC_DT,
					rec(j).AC_SLIP_TYP		AC_SLIP_TYP,
					rec(j).GI_DPT_CD		GI_DPT_CD,
					rec(j).GR_DPT_CD		GR_DPT_CD,
					rec(j).BD_DPT_CD		BD_DPT_CD,
					rec(j).LOC_CD			LOC_CD,
					rec(j).AC_ITM_GRP_CD	AC_ITM_GRP_CD,
					rec(j).ITM_JNL_CD		ITM_JNL_CD,
					rec(j).ITM_CD			ITM_CD,
					rec(j).ITM_SUB1			ITM_SUB1,
					rec(j).ITM_SUB2			ITM_SUB2,
					rec(j).ITM_SUB3			ITM_SUB3,
					rec(j).ITM_NM			ITM_NM,
					rec(j).LOT_NO			LOT_NO,
					rec(j).SUBLOT_NO		SUBLOT_NO,
					rec(j).SNO1				SNO1,
					rec(j).SNO2				SNO2,
					rec(j).SNO3				SNO3,
					rec(j).SNO4				SNO4,
					rec(j).SLO_NO			SLO_NO,
					rec(j).PO_NO			PO_NO,
					rec(j).IV_NO			IV_NO,
					rec(j).BASE_UNIT_CD		BASE_UNIT_CD,
					rec(j).BASE_UNIT_QTY	BASE_UNIT_QTY,
					rec(j).BASE_CUR_CD		BASE_CUR_CD,
					rec(j).AMT				AMT,
					rec(j).FOREIGN_FLG		FOREIGN_FLG,
					rec(j).JNL_FIN_CNT		JNL_FIN_CNT,
					rec(j).SRC_ALC_AC_CD	SRC_ALC_AC_CD,
					rec(j).ALC_AC_CD		ALC_AC_CD,
					rec(j).JNL_KEY1			JNL_KEY1,
					rec(j).JNL_KEY2			JNL_KEY2,
					rec(j).JNL_KEY3			JNL_KEY3,
					rec(j).JNL_KEY4			JNL_KEY4,
					rec(j).JNL_KEY5			JNL_KEY5,
					rec(j).JNL_KEY6			JNL_KEY6,
					rec(j).JNL_KEY7			JNL_KEY7,
					rec(j).JNL_KEY8			JNL_KEY8,
					rec(j).JNL_KEY9			JNL_KEY9,
					rec(j).JNL_KEY10		JNL_KEY10
				FROM DUAL
				) x
			ON (0=0
				AND t.WG_CD = x.WG_CD
				AND t.AC_YM = x.AC_YM
				AND t.CALC_GRP_CD = x.CALC_GRP_CD
				AND t.CALC_NO = x.CALC_NO
				AND t.AC_SLIP_TYP = x.AC_SLIP_TYP
				AND t.GI_DPT_CD = x.GI_DPT_CD
				AND t.GR_DPT_CD = x.GR_DPT_CD
				AND (t.LOC_CD IS NULL AND x.LOC_CD IS NULL OR t.LOC_CD = x.LOC_CD)
				AND t.ITM_CD = x.ITM_CD
				AND t.ITM_SUB1 = x.ITM_SUB1
				AND t.ITM_SUB2 = x.ITM_SUB2
				AND t.ITM_SUB3 = x.ITM_SUB3
				AND t.LOT_NO = x.LOT_NO
				AND t.SUBLOT_NO = x.SUBLOT_NO
				AND t.SNO1 = x.SNO1
				AND t.SNO2 = x.SNO2
				AND t.SNO3 = x.SNO3
				AND t.SNO4 = x.SNO4
				AND (t.SLO_NO IS NULL AND x.SLO_NO IS NULL OR t.SLO_NO = x.SLO_NO)
				AND (t.PO_NO IS NULL AND x.PO_NO IS NULL OR t.PO_NO = x.PO_NO)
				AND (t.IV_NO IS NULL AND x.IV_NO IS NULL OR t.IV_NO = x.IV_NO)
				AND t.SRC_ALC_AC_CD = x.SRC_ALC_AC_CD
				AND t.ALC_AC_CD = x.ALC_AC_CD
				)
			WHEN MATCHED THEN
				UPDATE SET t.AMT = t.AMT + x.AMT
			WHEN NOT MATCHED THEN
				INSERT	(
					DATA_NO,
					WG_CD, AC_YM, CALC_GRP_CD, CALC_NO, AC_DT, AC_SLIP_TYP,
					GI_DPT_CD, GR_DPT_CD, BD_DPT_CD, LOC_CD, AC_ITM_GRP_CD, ITM_JNL_CD,
					ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3, ITM_NM, LOT_NO, SUBLOT_NO,
					SNO1, SNO2, SNO3, SNO4, SLO_NO, PO_NO, IV_NO, BASE_UNIT_CD,
					BASE_UNIT_QTY, BASE_CUR_CD, AMT, FOREIGN_FLG, JNL_FIN_CNT,
					SRC_ALC_AC_CD, ALC_AC_CD, JNL_KEY1, JNL_KEY2, JNL_KEY3, JNL_KEY4,
					JNL_KEY5, JNL_KEY6, JNL_KEY7, JNL_KEY8, JNL_KEY9, JNL_KEY10
					)
				VALUES	(
					LPAD(MAPA_NUM.F_GET_SEQ(C_AC_COST_SEQ), C_IT_DAT_NO_L, '0'),
					x.WG_CD, x.AC_YM, x.CALC_GRP_CD, x.CALC_NO, x.AC_DT, x.AC_SLIP_TYP,
					x.GI_DPT_CD, x.GR_DPT_CD, x.BD_DPT_CD, x.LOC_CD, x.AC_ITM_GRP_CD, x.ITM_JNL_CD,
					x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3, x.ITM_NM, x.LOT_NO, x.SUBLOT_NO,
					x.SNO1, x.SNO2, x.SNO3, x.SNO4, x.SLO_NO, x.PO_NO, x.IV_NO, x.BASE_UNIT_CD,
					x.BASE_UNIT_QTY, x.BASE_CUR_CD, x.AMT, x.FOREIGN_FLG, x.JNL_FIN_CNT,
					x.SRC_ALC_AC_CD, x.ALC_AC_CD, x.JNL_KEY1, x.JNL_KEY2, x.JNL_KEY3, x.JNL_KEY4,
					x.JNL_KEY5, x.JNL_KEY6, x.JNL_KEY7, x.JNL_KEY8, x.JNL_KEY9, x.JNL_KEY10
					)
			;
		rec.DELETE ;
		i := 0 ;
	END IF ;
END ;
/*************************************************************************/
BEGIN

