	L_SLO_NO_DIFF_OUTSRC_SUM	:= '1' ;
	L_SLO_NO_DIFF_OUTSRC_PRI	:= '1' ;
	L_SLO_NO_DIFF_OUTSRC_RATE	:= '1' ;
