	L_PO_NO_ONR_PROV_DIFF		:= '1' ;
	L_PO_NO_IN_ONR_DIFF			:= '1' ;
	L_PO_NO_ITM_ALC				:= '1' ;
	L_PO_NO_DIFF_IO_SUM			:= '1' ;
	L_PO_NO_DIFF_IO_PRI			:= '1' ;
	L_PO_NO_DIFF_IO_RATE		:= '1' ;
	L_PO_NO_DIFF_QT_PAR			:= '1' ;
	L_PO_NO_DIFF_PR_PAR			:= '1' ;
	L_PO_NO_DIFF_QT_CHD			:= '1' ;
	L_PO_NO_DIFF_PR_CHD			:= '1' ;
	L_PO_NO_DIFF_WK				:= '1' ;
	L_PO_NO_DIFF_ACT1			:= '1' ;
	L_PO_NO_DIFF_ACT2			:= '1' ;
	L_PO_NO_DIFF_ACT3			:= '1' ;
