	L_PO_NO_DIFF_OUTSRC_PRI		:= '1' ;
	L_PO_NO_DIFF_OUTSRC_RATE	:= '1' ;
	L_PO_NO_DIFF_SS_PAR			:= '1' ;
	L_PO_NO_DIFF_SS_CHD			:= '1' ;
	L_PO_NO_DIFF_RATE_ALC		:= '1' ;
	L_PO_NO_DIFF_STD_ADJ		:= '1' ;
	L_IV_NO_SLS_CST				:= '1' ;
	L_IV_NO_ONR_PROV_DIFF		:= '1' ;
	L_IV_NO_IN_ONR_DIFF			:= '1' ;
	L_IV_NO_ITM_ALC				:= '1' ;
	L_IV_NO_DIFF_IO_SUM			:= '1' ;
	L_IV_NO_DIFF_IO_PRI			:= '1' ;
	L_IV_NO_DIFF_IO_RATE		:= '1' ;
	L_IV_NO_DIFF_QT_PAR			:= '1' ;
	L_IV_NO_DIFF_PR_PAR			:= '1' ;
	L_IV_NO_DIFF_QT_CHD			:= '1' ;
	L_IV_NO_DIFF_PR_CHD			:= '1' ;
	L_IV_NO_DIFF_WK				:= '1' ;
	L_IV_NO_DIFF_ACT1			:= '1' ;
	L_IV_NO_DIFF_ACT2			:= '1' ;
	L_IV_NO_DIFF_ACT3			:= '1' ;
	L_IV_NO_DIFF_ACT4			:= '1' ;
	L_IV_NO_DIFF_ACT5			:= '1' ;
	L_IV_NO_DIFF_RATE_ITM		:= '1' ;
	L_IV_NO_DIFF_OUTSRC_SUM		:= '1' ;
	L_IV_NO_DIFF_OUTSRC_PRI		:= '1' ;
	L_IV_NO_DIFF_OUTSRC_RATE	:= '1' ;
	L_IV_NO_DIFF_SS_PAR			:= '1' ;
	L_IV_NO_DIFF_SS_CHD			:= '1' ;
	L_IV_NO_DIFF_RATE_ALC		:= '1' ;
	L_IV_NO_DIFF_STD_ADJ		:= '1' ;
	L_REV_IN_STKTK_FLG			:= '0' ;
	L_REV_OTH_CCN_GR_FLG		:= '0' ;

	FOR z1 IN (
		SELECT	m.AC_SLIP_TYP,
			m.ITM_SUM_FLG,
			m.SLO_NO_FLG,
			m.PO_NO_FLG,
			m.IV_NO_FLG
		FROM	MAM_COST_SLIP_JNL m
		WHERE	0=0
		AND	m.CALC_GRP_CD = I_CALC_GRP_CD
		)
	LOOP
		IF z1.AC_SLIP_TYP = C_AC_SLIP_COMP_CST THEN
			L_COMP_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_SLS_CST THEN
			L_SLS_FLG := '1' ;
			L_ITM_SUM_SLS_CST := z1.ITM_SUM_FLG ;
			L_SLO_NO_SLS_CST := z1.SLO_NO_FLG ;
			L_PO_NO_SLS_CST := z1.PO_NO_FLG ;
			L_IV_NO_SLS_CST := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_MFG THEN
			L_MFG_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_PURC_COST THEN	
			L_PURC_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP IN (C_AC_SLIP_EOM_STK_PROD, C_AC_SLIP_EOM_STK_SLS) THEN
			L_STK_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_INP_WIP_CST THEN
			L_WIP_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP IN (
			C_AC_SLIP_INPUT, C_AC_SLIP_IN_ONR,
			C_AC_SLIP_IN_SS, C_AC_SLIP_BYPROD
			) THEN
			L_INPT_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_CST_IO_AOD THEN
			L_ADJ_FLG := '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_ONR_PROV_DIFF THEN
			L_IO_ONR_FLG := '1' ;
			L_ITM_SUM_ONR_PROV_DIFF := z1.ITM_SUM_FLG ;
			L_SLO_NO_ONR_PROV_DIFF := z1.SLO_NO_FLG ;
			L_PO_NO_ONR_PROV_DIFF := z1.PO_NO_FLG ;
			L_IV_NO_ONR_PROV_DIFF := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_IN_ONR_DIFF THEN
			L_INPT_ONR_FLG := '1' ;
			L_ITM_SUM_IN_ONR_DIFF := z1.ITM_SUM_FLG ;
			L_SLO_NO_IN_ONR_DIFF := z1.SLO_NO_FLG ;
			L_PO_NO_IN_ONR_DIFF := z1.PO_NO_FLG ;
			L_IV_NO_IN_ONR_DIFF := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_STK_ASM_DIFF THEN
			L_ST_DIFF_FLG := '1' ;
			L_ITM_SUM_STK_ASM_DIFF := z1.ITM_SUM_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_EOM_STK_ASM_MIS THEN
			L_STK_LOSS_FLG := '1' ;
			L_ITM_SUM_EOM_STK_ASM_MIS := z1.ITM_SUM_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_GR THEN
			L_PROD_ITM_FLG	:= '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_RET_GR THEN
			L_PROD_ITM_RET_FLG	:= '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DPT_XFR_GR THEN
			L_DPT_XFR_FLG	:= '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_DIFF THEN
			L_PROD_ITM_DIFF_FLG	:= '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_RET_DIFF THEN
			L_PROD_ITM_RET_DIFF_FLG	:= '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DPT_XFR_DIFF THEN
			L_DPT_XFR_DIFF_FLG	:= '1' ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_ITM_ALC THEN
			L_ITM_ALC_FLG	:= '1' ;
			L_ITM_SUM_ITM_ALC := z1.ITM_SUM_FLG ;
			L_SLO_NO_ITM_ALC := z1.SLO_NO_FLG ;
			L_PO_NO_ITM_ALC := z1.PO_NO_FLG ;
			L_IV_NO_ITM_ALC := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_IO_SUM THEN
			L_DIFF_IO_SUM_FLG	:= '1' ;
			L_ITM_SUM_DIFF_IO_SUM := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_IO_SUM := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_IO_SUM := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_IO_SUM := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_IO_PRI THEN
			L_DIFF_IO_PRI_FLG	:= '1' ;
			L_ITM_SUM_DIFF_IO_PRI := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_IO_PRI := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_IO_PRI := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_IO_PRI := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_IO_RATE THEN
			L_DIFF_IO_RATE_FLG	:= '1' ;
			L_ITM_SUM_DIFF_IO_RATE := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_IO_RATE := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_IO_RATE := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_IO_RATE := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_QT_PAR THEN
			L_DIFF_QT_PAR_FLG	:= '1' ;
			L_ITM_SUM_DIFF_QT_PAR := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_QT_PAR := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_QT_PAR := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_QT_PAR := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_PR_PAR THEN
			L_DIFF_PR_PAR_FLG	:= '1' ;
			L_ITM_SUM_DIFF_PR_PAR := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_PR_PAR := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_PR_PAR := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_PR_PAR := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_QT_CHD THEN
			L_DIFF_QT_CHD_FLG	:= '1' ;
			L_ITM_SUM_DIFF_QT_CHD := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_QT_CHD := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_QT_CHD := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_QT_CHD := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_PR_CHD THEN
			L_DIFF_PR_CHD_FLG	:= '1' ;
			L_ITM_SUM_DIFF_PR_CHD := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_PR_CHD := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_PR_CHD := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_PR_CHD := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_WK THEN
			L_DIFF_WK_FLG	:= '1' ;
			L_ITM_SUM_DIFF_WK := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_WK := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_WK := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_WK := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT1 THEN
			L_DIFF_ACT1_FLG	:= '1' ;
			L_ITM_SUM_DIFF_ACT1 := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_ACT1 := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_ACT1 := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_ACT1 := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT2 THEN
			L_DIFF_ACT2_FLG	:= '1' ;
			L_ITM_SUM_DIFF_ACT2 := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_ACT2 := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_ACT2 := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_ACT2 := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT3 THEN
			L_DIFF_ACT3_FLG	:= '1' ;
			L_ITM_SUM_DIFF_ACT3 := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_ACT3 := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_ACT3 := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_ACT3 := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT4 THEN
			L_DIFF_ACT4_FLG	:= '1' ;
			L_ITM_SUM_DIFF_ACT4 := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_ACT4 := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_ACT4 := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_ACT4 := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT5 THEN
			L_DIFF_ACT5_FLG	:= '1' ;
			L_ITM_SUM_DIFF_ACT5 := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_ACT5 := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_ACT5 := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_ACT5 := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_RATE_ITM THEN
			L_DIFF_RATE_ITM_FLG	:= '1' ;
			L_ITM_SUM_DIFF_RATE_ITM := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_RATE_ITM := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_RATE_ITM := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_RATE_ITM := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_OUTSRC_SUM THEN
			L_DIFF_OUTSRC_SUM_FLG	:= '1' ;
			L_ITM_SUM_DIFF_OUTSRC_SUM := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_OUTSRC_SUM := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_OUTSRC_SUM := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_OUTSRC_SUM := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_OUTSRC_PRI THEN
			L_DIFF_OUTSRC_PRI_FLG	:= '1' ;
			L_ITM_SUM_DIFF_OUTSRC_PRI := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_OUTSRC_PRI := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_OUTSRC_PRI := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_OUTSRC_PRI := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_OUTSRC_RATE THEN
			L_DIFF_OUTSRC_RATE_FLG	:= '1' ;
			L_ITM_SUM_DIFF_OUTSRC_RATE := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_OUTSRC_RATE := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_OUTSRC_RATE := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_OUTSRC_RATE := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_SS_PAR THEN
			L_DIFF_SS_PAR_FLG	:= '1' ;
			L_ITM_SUM_DIFF_SS_PAR := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_SS_PAR := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_SS_PAR := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_SS_PAR := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_SS_CHD THEN
			L_DIFF_SS_CHD_FLG	:= '1' ;
			L_ITM_SUM_DIFF_SS_CHD := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_SS_CHD := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_SS_CHD := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_SS_CHD := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_RATE_ALC THEN
			L_DIFF_RATE_ALC_FLG	:= '1' ;
			L_ITM_SUM_DIFF_RATE_ALC := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_RATE_ALC := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_RATE_ALC := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_RATE_ALC := z1.IV_NO_FLG ;

		ELSIF z1.AC_SLIP_TYP = C_AC_SLIP_DIFF_STD_ADJ THEN
			L_DIFF_STD_ADJ_FLG	:= '1' ;
			L_ITM_SUM_DIFF_STD_ADJ := z1.ITM_SUM_FLG ;
			L_SLO_NO_DIFF_STD_ADJ := z1.SLO_NO_FLG ;
			L_PO_NO_DIFF_STD_ADJ := z1.PO_NO_FLG ;
			L_IV_NO_DIFF_STD_ADJ := z1.IV_NO_FLG ;

		ELSE
			NULL ;
		END IF ;
	END LOOP ;

	INVALID_RSN_REC.DELETE ;
	FOR z2 IN (
		SELECT	m.PARM_VAL
		FROM	MGT_PARM m
		WHERE	0=0
		AND	m.CALC_GRP_CD = I_CALC_GRP_CD
		AND	m.PARM_KEY = 'ETC_AC_RSN_INVALID'
		)
	LOOP
		IF z2.PARM_VAL = '1' THEN
			FOR z3 IN (
				SELECT	m.AC_RSN_CD,
					m.AC_INVALID_FLG
				FROM	MAM_AC_RSN m
				WHERE	0=0
				AND	m.AC_INVALID_FLG = '1'
				AND	m.DEL_FLG = '0'
				)
			LOOP
				INVALID_RSN_REC(z3.AC_RSN_CD) := z3.AC_INVALID_FLG ;
			END LOOP ;
		END IF ;
	END LOOP ;

	FOR z3 IN (
		SELECT	m.PARM_KEY,
			m.PARM_VAL
		FROM	MGT_PARM m
		WHERE	0=0
		AND	m.CALC_GRP_CD = I_CALC_GRP_CD
		AND	m.PARM_KEY IN ('ETC_AC_IN_STKTK', 'ETC_AC_OTH_CCN_GR')
		AND	m.PARM_VAL = '1'
		)
	LOOP
		IF z3.PARM_KEY = 'ETC_AC_IN_STKTK' THEN
			L_REV_IN_STKTK_FLG := '1' ;
		END IF ;

		IF z3.PARM_KEY = 'ETC_AC_OTH_CCN_GR' THEN
			L_REV_OTH_CCN_GR_FLG := '1' ;
		END IF ;
	END LOOP ;

	DELETE	MBT_AC_COST t
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.AC_YM = I_YM
	;

	L_PARM := MAPA_COMM.F_GET_PARM('ITM_SUB_TYP') ;
	-- 仕訳キー対応マスタの取得
	L_CNT := 0 ;
	JNL_KEY_MAP_REC.DELETE ;
	FOR r IN (
		SELECT	*
		FROM	MAM_JNL_KEY_MAP m
		WHERE	0=0
		AND	m.COST_FLG = G_ON
		ORDER BY m.AC_SLIP_TYP, m.JNL_KEY_COL_TYP
		)
	LOOP
		L_CNT := L_CNT + 1 ;
		JNL_KEY_MAP_REC(L_CNT) := r ;
	END LOOP ;


	DPT_MAP_REC.DELETE ;
	i := 0 ;
	sum_i := 0 ;
	FOR x IN (
		-- 投入・売上以外に関する受払原価
		SELECT	x1.CALC_REC_TYP, x1.COST_IO_TYP,
			x1.WG_CD,
			x1.MNG_DPT_CD		DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3,
			x1.ITM_NM, x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD,
			x1.BP_CD, x1.STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.OTHER_DPT_CD		DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			SUM(x1.QTY)		QTY,
			x1.TRD_GRP,
			SUM(x1.ACT_COST)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			m1.AREA_CD,
			m1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			x1.ITM_GRP_CD1,
			x1.ITM_GRP_CD2,
			x1.ITM_GRP_CD3,
			x1.ITM_GRP_CD4,
			x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6,
			x1.ITM_GRP_CD7,
			x1.ITM_GRP_CD8,
			x1.ITM_GRP_CD9,
			x1.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			SELECT	t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				DECODE(m5.PO_NO_FLG, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(m5.SLO_NO_FLG, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(m5.IV_NO_FLG, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.TRD_GRP) TRD_GRP,
				NVL(SUM(t2.ACT_COST), 0)	ACT_COST,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	(
				SELECT /*+INDEX(T MGT_ACC_TOP_ALL_IE01)*/
					t.CALC_GRP_CD, t.CALC_NO, t.TOP_REC_NO,
					t.CALC_REC_TYP, t.COST_IO_TYP,
					t.WG_CD, t.MNG_DPT_CD,
					t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
					t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
					t.AC_RSN_CD,
					t.LOC_CD, t.STR_LN_CD,
					t.BP_CD, t.STK_BP_CD,
					t.PO_NO, t.SLO_NO, t.IV_NO,
					DECODE(t.CALC_REC_TYP, C_CALC_REC_PURC, t.ALC_DPT_CD, t.OTHER_DPT_CD) OTHER_DPT_CD,
					t.ASST_TYP,
					t.REPURC_OBLI_FLG,
					t.QTY,
					t.TRD_GRP,
					DECODE(t.CALC_REC_TYP,
						C_CALC_REC_END_STK,
							DECODE(t.ASST_TYP,
								C_ASST_PROD, C_AC_SLIP_EOM_STK_PROD,
								C_AC_SLIP_EOM_STK_SLS
								),
						C_CALC_REC_END_WIP, C_AC_SLIP_INP_WIP_CST,
						C_CALC_REC_COMP, C_AC_SLIP_COMP_CST,
						C_CALC_REC_INST, C_AC_SLIP_MFG,
						C_CALC_REC_PURC, C_AC_SLIP_PURC_COST,
						C_CALC_REC_IO,
							DECODE(t.COST_IO_TYP,
								C_COST_IO_FFR_PROV, C_AC_SLIP_FFR_PROV_CST,
								C_COST_IO_ONR_PROV, C_AC_SLIP_ONR_PROV_CST,
								C_COST_IO_STK_IN,
									DECODE(t.AC_SLIP_TYP,
										C_AC_SLIP_PROD_ITM_SO, C_AC_SLIP_PROD_ITM_GR,
										C_AC_SLIP_PROD_ITM_RET_SO, C_AC_SLIP_PROD_ITM_RET_GR,
										C_AC_SLIP_DPT_XFR_SO, C_AC_SLIP_DPT_XFR_GR,
										t.AC_SLIP_TYP
										),
								t.AC_SLIP_TYP
								),
						C_CALC_REC_ADJ, C_AC_SLIP_CST_IO_AOD,
						NULL
						)	AC_SLIP_TYP
				FROM	MGT_ACC_TOP t
				WHERE	0=0
				AND	t.CALC_NO = I_CALC_NO
				AND	t.CALC_GRP_CD = I_CALC_GRP_CD
				AND	t.ASST_TYP IN (C_ASST_PROD, C_ASST_SLS)
				AND	(
					L_COMP_FLG = '1' AND t.CALC_REC_TYP = C_CALC_REC_COMP
					OR
					L_MFG_FLG = '1' AND t.CALC_REC_TYP = C_CALC_REC_INST
					OR
					L_PURC_FLG = '1' AND t.CALC_REC_TYP = C_CALC_REC_PURC
					OR
					t.CALC_REC_TYP = C_CALC_REC_IO
					OR
					L_STK_FLG = '1' AND t.CALC_REC_TYP = C_CALC_REC_END_STK AND t.YM = I_YM
					OR
					L_WIP_FLG = '1' AND t.CALC_REC_TYP = C_CALC_REC_END_WIP AND t.YM = I_YM
					OR
					L_ADJ_FLG = '1' AND t.CALC_REC_TYP = C_CALC_REC_ADJ
					)
				) t1,
				MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_SUNDRY_ITM m4, MAM_COST_SLIP_JNL m5
			WHERE	0=0
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t2.EXPNS_TYP(+) = C_ENPNS_PRD
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	t1.CALC_GRP_CD = m5.CALC_GRP_CD(+)
			AND	t1.AC_SLIP_TYP = m5.AC_SLIP_TYP(+)
			AND	(
				m5.CALC_GRP_CD IS NOT NULL
				OR
				L_PROD_ITM_DIFF_FLG = '1' AND t1.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_GR
				OR
				L_PROD_ITM_RET_DIFF_FLG = '1' AND t1.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_RET_GR
				OR
				L_DPT_XFR_DIFF_FLG = '1' AND t1.AC_SLIP_TYP = C_AC_SLIP_DPT_XFR_GR
				OR
				L_PURC_FLG = '1' AND t1.AC_SLIP_TYP = C_AC_SLIP_PURC
				)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = t1.AC_SLIP_TYP
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			GROUP BY t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM),
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.PO_NO, t1.SLO_NO, t1.IV_NO,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t1.TRD_GRP,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10,
				m5.ITM_SUM_FLG,
				m5.PO_NO_FLG, m5.SLO_NO_FLG, m5.IV_NO_FLG
			) x1, MAM_BP m1
		WHERE	0=0
		AND	NVL(x1.STK_BP_CD, x1.BP_CD) = m1.BP_CD(+)
		AND	m1.DEL_FLG(+) = '0'
		GROUP BY x1.CALC_REC_TYP, x1.COST_IO_TYP,
			x1.WG_CD, x1.MNG_DPT_CD,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3,
			x1.ITM_NM, x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD,
			x1.BP_CD, x1.STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.OTHER_DPT_CD,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.TRD_GRP,
			m1.AREA_CD, m1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10
		UNION ALL
		-- 投入に関する原価
		SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
			x2.CALC_REC_TYP, x2.COST_IO_TYP,
			x2.WG_CD,
			x2.MNG_DPT_CD		DPT_CD1,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_CD) ITM_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_SUB1) ITM_SUB1,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_SUB2) ITM_SUB2,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_SUB3) ITM_SUB3,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_NM) ITM_NM,
			x2.ITM_JNL_CD, x2.AC_ITM_GRP_CD, x2.UNIT_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.LOT_NO) LOT_NO,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.SUBLOT_NO) SUBLOT_NO,
			x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
			x2.AC_SLIP_TYP, x2.AC_RSN_CD,
			x2.LOC_CD, x2.STR_LN_CD,
			x2.BP_CD, x2.STK_BP_CD,
			DECODE(m5.PO_NO_FLG, G_OFF, NULL, t1.PO_NO) PO_NO,
			DECODE(m5.SLO_NO_FLG, G_OFF, NULL, t1.SLO_NO) SLO_NO,
			DECODE(m5.IV_NO_FLG, G_OFF, NULL, t1.IV_NO) IV_NO,
			t1.MNG_DPT_CD		DPT_CD2,
			x2.ASST_TYP,
			x2.REPURC_OBLI_FLG,
			SUM(x2.QTY)	QTY,
			NULL		TRD_GRP,
			SUM(x2.ACT_COST)	AMT,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_CD) TRD_ITM_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_SUB1) TRD_ITM_SUB1,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_SUB2) TRD_ITM_SUB2,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_SUB3) TRD_ITM_SUB3,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) TRD_ITM_NM,
			m1.ITM_JNL_CD	TRD_ITM_JNL_CD,
			m1.AC_ITM_GRP_CD	TRD_AC_ITM_GRP_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.LOT_NO) TRD_LOT_NO,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.SUBLOT_NO) TRD_SUBLOT_NO,
			t1.SNO1		TRD_SNO1,
			t1.SNO2		TRD_SNO2,
			t1.SNO3		TRD_SNO3,
			t1.SNO4		TRD_SNO4,
			m2.AREA_CD,
			m2.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD1) ITM_GRP_CD1,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD2) ITM_GRP_CD2,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD3) ITM_GRP_CD3,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD4) ITM_GRP_CD4,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD5) ITM_GRP_CD5,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD6) ITM_GRP_CD6,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD7) ITM_GRP_CD7,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD8) ITM_GRP_CD8,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD9) ITM_GRP_CD9,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD10) ITM_GRP_CD10,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD1) TRD_ITM_GRP_CD1,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD2) TRD_ITM_GRP_CD2,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD3) TRD_ITM_GRP_CD3,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD4) TRD_ITM_GRP_CD4,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD5) TRD_ITM_GRP_CD5,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD6) TRD_ITM_GRP_CD6,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD7) TRD_ITM_GRP_CD7,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD8) TRD_ITM_GRP_CD8,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD9) TRD_ITM_GRP_CD9,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD10) TRD_ITM_GRP_CD10
		FROM	(
			SELECT	t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP, t1.YM,
				t1.WG_CD, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t1.ITM_MFG_INST_NO,
				t1.MFG_ACT_NO,
				t1.PAR_ITM_CD, t1.PAR_ITM_SUB1, t1.PAR_ITM_SUB2, t1.PAR_ITM_SUB3,
				NVL(SUM(t2.ACT_COST), 0)	ACT_COST,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10
			FROM	(
				SELECT /*+INDEX(T MGT_ACC_TOP_ALL_IE01)*/
					t.CALC_GRP_CD, t.CALC_NO, t.TOP_REC_NO, t.YM,
					t.CALC_REC_TYP, t.COST_IO_TYP,
					t.WG_CD, t.MNG_DPT_CD,
					t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
					t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
					t.AC_RSN_CD,
					t.LOC_CD, t.STR_LN_CD,
					t.BP_CD, t.STK_BP_CD,
					t.OTHER_DPT_CD,
					t.ASST_TYP,
					t.REPURC_OBLI_FLG,
					t.QTY,
					t.ITM_MFG_INST_NO,
					t.MFG_ACT_NO,
					t.PAR_ITM_CD,
					t.PAR_ITM_SUB1,
					t.PAR_ITM_SUB2,
					t.PAR_ITM_SUB3,
					DECODE(t.ASST_TYP,
						C_ASST_OTH,
							DECODE(t.AC_SLIP_TYP,
								C_AC_SLIP_IN_SS, C_AC_SLIP_IN_SS,
								C_AC_SLIP_IN_ONR
								),
						DECODE(t.AC_SLIP_TYP,
							C_AC_SLIP_BYPROD, t.AC_SLIP_TYP,
							CASE
								WHEN t.REPURC_OBLI_FLG = '1' THEN C_AC_SLIP_IN_ONR
								ELSE C_AC_SLIP_INPUT
							END
							)
						)	AC_SLIP_TYP
				FROM	MGT_ACC_TOP t
				WHERE	0=0
				AND	t.CALC_NO = I_CALC_NO
				AND	t.CALC_GRP_CD = I_CALC_GRP_CD
				AND	t.CALC_REC_TYP = C_CALC_REC_INPT
				AND	L_INPT_FLG = '1'
				) t1,
				MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t2.EXPNS_TYP(+) = C_ENPNS_PRD
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = t1.AC_SLIP_TYP
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			GROUP BY t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP, t1.YM,
				t1.WG_CD, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM),
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t1.ITM_MFG_INST_NO,
				t1.MFG_ACT_NO,
				t1.PAR_ITM_CD, t1.PAR_ITM_SUB1, t1.PAR_ITM_SUB2, t1.PAR_ITM_SUB3,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10
			) x2,
			MGT_ACC_TOP t1, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4, MAM_COST_SLIP_JNL m5
		WHERE	0=0
		AND	t1.CALC_NO = I_CALC_NO
		AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
		AND	t1.ITM_CD = x2.PAR_ITM_CD
		AND	t1.ITM_SUB1 = x2.PAR_ITM_SUB1
		AND	t1.ITM_SUB2 = x2.PAR_ITM_SUB2
		AND	t1.ITM_SUB3 = x2.PAR_ITM_SUB3
		AND	t1.ITM_MFG_INST_NO = x2.ITM_MFG_INST_NO
		AND	t1.MFG_ACT_NO = x2.MFG_ACT_NO
		AND	t1.YM = x2.YM
		AND	t1.CALC_REC_TYP = C_CALC_REC_INST
		AND	t1.ITM_CD = m1.ITM_CD(+)
		AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.DEL_FLG(+) = '0'
		AND	m1.RELEASE_FLG(+) = '1'
		AND	t1.ITM_CD = m4.ITM_CD(+)
		AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
		AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
		AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
		AND	t1.SNO1 = m4.SNO1(+)
		AND	t1.SNO2 = m4.SNO2(+)
		AND	t1.SNO3 = m4.SNO3(+)
		AND	t1.SNO4 = m4.SNO4(+)
		AND	x2.BP_CD = m2.BP_CD(+)
		AND	m2.DEL_FLG(+) = '0'
		AND	m5.CALC_GRP_CD = I_CALC_GRP_CD AND m5.AC_SLIP_TYP = x2.AC_SLIP_TYP
		GROUP BY x2.CALC_REC_TYP, x2.COST_IO_TYP,
			x2.WG_CD, x2.MNG_DPT_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_CD),
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_SUB1),
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_SUB2),
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.ITM_SUB3),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_NM),
			x2.ITM_JNL_CD, x2.AC_ITM_GRP_CD, x2.UNIT_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.LOT_NO),
			DECODE(m5.ITM_SUM_FLG, G_ON, G_NULL_VAL, x2.SUBLOT_NO),
			x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
			x2.AC_SLIP_TYP, x2.AC_RSN_CD,
			x2.LOC_CD, x2.STR_LN_CD,
			x2.BP_CD, x2.STK_BP_CD,
			DECODE(m5.PO_NO_FLG, G_OFF, NULL, t1.PO_NO),
			DECODE(m5.SLO_NO_FLG, G_OFF, NULL, t1.SLO_NO),
			DECODE(m5.IV_NO_FLG, G_OFF, NULL, t1.IV_NO),
			t1.MNG_DPT_CD,
			x2.ASST_TYP,
			x2.REPURC_OBLI_FLG,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_CD),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_SUB1),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_SUB2),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.ITM_SUB3),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)),
			m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.LOT_NO),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, t1.SUBLOT_NO),
			t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
			m2.AREA_CD, m2.CNTRY_CD,
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD1),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD2),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD3),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD4),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD5),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD6),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD7),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD8),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD9),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, x2.ITM_GRP_CD10),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD1),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD2),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD3),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD4),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD5),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD6),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD7),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD8),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD9),
			DECODE(m5.ITM_SUM_FLG, G_ON, NULL, m1.ITM_GRP_CD10)
		UNION ALL
		-- 売上に関する原価
		SELECT	x3.CALC_REC_TYP, x3.COST_IO_TYP,
			x3.WG_CD,
			x3.MNG_DPT_CD		DPT_CD1,
			x3.ITM_CD, x3.ITM_SUB1, x3.ITM_SUB2, x3.ITM_SUB3,
			x3.ITM_NM, x3.ITM_JNL_CD, x3.AC_ITM_GRP_CD, x3.UNIT_CD,
			x3.LOT_NO, x3.SUBLOT_NO, x3.SNO1, x3.SNO2, x3.SNO3, x3.SNO4,
			x3.AC_SLIP_TYP, x3.AC_RSN_CD,
			x3.LOC_CD, x3.STR_LN_CD,
			x3.BP_CD, x3.STK_BP_CD,
			x3.PO_NO, x3.SLO_NO, x3.IV_NO,
			x3.OTHER_DPT_CD		DPT_CD2,
			x3.ASST_TYP,
			x3.REPURC_OBLI_FLG,
			SUM(x3.QTY)	QTY,
			NULL		TRD_GRP,
			SUM(x3.ACT_COST) AMT,
			NULL		TRD_ITM_CD,
			NULL		TRD_ITM_SUB1,
			NULL		TRD_ITM_SUB2,
			NULL		TRD_ITM_SUB3,
			NULL		TRD_ITM_NM,
			NULL		TRD_ITM_JNL_CD,
			NULL		TRD_AC_ITM_GRP_CD,
			NULL		TRD_LOT_NO,
			NULL		TRD_SUBLOT_NO,
			NULL		TRD_SNO1,
			NULL		TRD_SNO2,
			NULL		TRD_SNO3,
			NULL		TRD_SNO4,
			m1.AREA_CD,
			m1.CNTRY_CD,
			x3.SLS_DPT_CD,
			x3.SLS_USR_CD	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			x3.ITM_GRP_CD1,
			x3.ITM_GRP_CD2,
			x3.ITM_GRP_CD3,
			x3.ITM_GRP_CD4,
			x3.ITM_GRP_CD5,
			x3.ITM_GRP_CD6,
			x3.ITM_GRP_CD7,
			x3.ITM_GRP_CD8,
			x3.ITM_GRP_CD9,
			x3.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			SELECT	t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				DECODE(L_PO_NO_SLS_CST, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_SLS_CST, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_SLS_CST, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t3.SLS_DPT_CD, t3.SLS_USR_CD,
				NVL(SUM(t2.ACT_COST), 0)	ACT_COST,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_SLS_CST, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	(
				SELECT /*+INDEX(T MGT_ACC_TOP_ALL_IE01)*/
					t.CALC_GRP_CD, t.CALC_NO, t.TOP_REC_NO,
					t.CALC_REC_TYP, t.COST_IO_TYP,
					t.ACT_ID, t.ACT_ID_SUB,
					t.WG_CD, t.MNG_DPT_CD,
					t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
					t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
					t.AC_RSN_CD,
					t.LOC_CD, t.STR_LN_CD,
					t.BP_CD, t.STK_BP_CD,
					t.PO_NO, t.SLO_NO, t.IV_NO,
					t.OTHER_DPT_CD,
					t.ASST_TYP,
					t.REPURC_OBLI_FLG,
					t.QTY,
					C_AC_SLIP_SLS_CST		AC_SLIP_TYP
				FROM	MGT_ACC_TOP t
				WHERE	0=0
				AND	t.CALC_NO = I_CALC_NO
				AND	t.CALC_GRP_CD = I_CALC_GRP_CD
				AND	t.ASST_TYP IN (C_ASST_PROD, C_ASST_SLS)
				AND	t.CALC_REC_TYP = C_CALC_REC_SLS
				AND	L_SLS_FLG = '1'
				) t1,
				MGT_ACC_SML_COST t2, MGT_CALC_SLS t3, MAM_ITM_SRCH m1, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t2.EXPNS_TYP(+) = C_ENPNS_PRD
			AND	t1.CALC_NO = t3.CALC_NO
			AND	t1.CALC_GRP_CD = t3.CALC_GRP_CD
			AND	t1.ACT_ID = t3.ACT_SLS_ID
			AND	t1.ACT_ID_SUB = t3.ACT_SLS_ID_SUB
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	EXISTS	(
					SELECT	'X'
					FROM	MAM_COST_SLIP_JNL m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = t1.AC_SLIP_TYP
					)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = t1.AC_SLIP_TYP
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			GROUP BY t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM),
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.PO_NO, t1.SLO_NO, t1.IV_NO,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t3.SLS_DPT_CD, t3.SLS_USR_CD,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10
			) x3,
			MAM_BP m1
		WHERE	0=0
		AND	x3.BP_CD = m1.BP_CD(+)
		AND	m1.DEL_FLG(+) = '0'
		GROUP BY x3.CALC_REC_TYP, x3.COST_IO_TYP,
			x3.WG_CD, x3.MNG_DPT_CD,
			x3.ITM_CD, x3.ITM_SUB1, x3.ITM_SUB2, x3.ITM_SUB3,
			x3.ITM_NM, x3.ITM_JNL_CD, x3.AC_ITM_GRP_CD, x3.UNIT_CD,
			x3.LOT_NO, x3.SUBLOT_NO, x3.SNO1, x3.SNO2, x3.SNO3, x3.SNO4,
			x3.AC_SLIP_TYP, x3.AC_RSN_CD,
			x3.LOC_CD, x3.STR_LN_CD,
			x3.BP_CD, x3.STK_BP_CD,
			x3.PO_NO, x3.SLO_NO, x3.IV_NO,
			x3.OTHER_DPT_CD,
			x3.ASST_TYP,
			x3.REPURC_OBLI_FLG,
			m1.AREA_CD, m1.CNTRY_CD,
			x3.SLS_DPT_CD, x3.SLS_USR_CD,
			x3.ITM_GRP_CD1, x3.ITM_GRP_CD2, x3.ITM_GRP_CD3, x3.ITM_GRP_CD4, x3.ITM_GRP_CD5,
			x3.ITM_GRP_CD6, x3.ITM_GRP_CD7, x3.ITM_GRP_CD8, x3.ITM_GRP_CD9, x3.ITM_GRP_CD10
		UNION ALL
		-- 有償支給差益
		SELECT	x4.CALC_REC_TYP, x4.COST_IO_TYP,
			x4.WG_CD,
			x4.MNG_DPT_CD		DPT_CD1,
			x4.ITM_CD, x4.ITM_SUB1, x4.ITM_SUB2, x4.ITM_SUB3,
			x4.ITM_NM, x4.ITM_JNL_CD, x4.AC_ITM_GRP_CD, x4.UNIT_CD,
			x4.LOT_NO, x4.SUBLOT_NO, x4.SNO1, x4.SNO2, x4.SNO3, x4.SNO4,
			x4.AC_SLIP_TYP, x4.AC_RSN_CD,
			x4.LOC_CD, x4.STR_LN_CD,
			x4.BP_CD, x4.STK_BP_CD,
			x4.PO_NO, x4.SLO_NO, x4.IV_NO,
			x4.OTHER_DPT_CD		DPT_CD2,
			x4.ASST_TYP,
			x4.REPURC_OBLI_FLG,
			SUM(x4.QTY)	QTY,
			NULL		TRD_GRP,
			SUM(x4.ACT_COST) AMT,
			NULL		TRD_ITM_CD,
			NULL		TRD_ITM_SUB1,
			NULL		TRD_ITM_SUB2,
			NULL		TRD_ITM_SUB3,
			NULL		TRD_ITM_NM,
			NULL		TRD_ITM_JNL_CD,
			NULL		TRD_AC_ITM_GRP_CD,
			NULL		TRD_LOT_NO,
			NULL		TRD_SUBLOT_NO,
			NULL		TRD_SNO1,
			NULL		TRD_SNO2,
			NULL		TRD_SNO3,
			NULL		TRD_SNO4,
			m1.AREA_CD,
			m1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			x4.ITM_GRP_CD1,
			x4.ITM_GRP_CD2,
			x4.ITM_GRP_CD3,
			x4.ITM_GRP_CD4,
			x4.ITM_GRP_CD5,
			x4.ITM_GRP_CD6,
			x4.ITM_GRP_CD7,
			x4.ITM_GRP_CD8,
			x4.ITM_GRP_CD9,
			x4.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			SELECT	t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				DECODE(L_PO_NO_ONR_PROV_DIFF, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_ONR_PROV_DIFF, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_ONR_PROV_DIFF, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t1.AMT - NVL(SUM(t2.ACT_COST), 0)	ACT_COST,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_ONR_PROV_DIFF, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	(
				SELECT /*+INDEX(T MGT_ACC_TOP_ALL_IE01)*/
					t.CALC_GRP_CD, t.CALC_NO, t.TOP_REC_NO,
					t.CALC_REC_TYP, t.COST_IO_TYP,
					t.ACT_ID, t.ACT_ID_SUB,
					t.WG_CD, t.MNG_DPT_CD,
					t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
					t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
					t.AC_RSN_CD,
					t.LOC_CD, t.STR_LN_CD,
					t.BP_CD, t.STK_BP_CD,
					t.PO_NO, t.SLO_NO, t.IV_NO,
					t.OTHER_DPT_CD,
					t.ASST_TYP,
					t.REPURC_OBLI_FLG,
					t.QTY,
					NVL(t.AMT, 0)	AMT,
					C_AC_SLIP_ONR_PROV_DIFF	AC_SLIP_TYP
				FROM	MGT_ACC_TOP t
				WHERE	0=0
				AND	t.CALC_NO = I_CALC_NO
				AND	t.CALC_GRP_CD = I_CALC_GRP_CD
				AND	t.CALC_REC_TYP = C_CALC_REC_IO
				AND	t.COST_IO_TYP = C_COST_IO_ONR_PROV
				AND	L_IO_ONR_FLG = '1'
				) t1,
				MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t2.EXPNS_TYP(+) = C_ENPNS_PRD
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = t1.AC_SLIP_TYP
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			GROUP BY t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM),
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.PO_NO, t1.SLO_NO, t1.IV_NO,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY, t1.AMT,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10
			) x4,
			MAM_BP m1
		WHERE	0=0
		AND	x4.BP_CD = m1.BP_CD(+)
		AND	m1.DEL_FLG(+) = '0'
		GROUP BY x4.CALC_REC_TYP, x4.COST_IO_TYP,
			x4.WG_CD, x4.MNG_DPT_CD,
			x4.ITM_CD, x4.ITM_SUB1, x4.ITM_SUB2, x4.ITM_SUB3,
			x4.ITM_NM, x4.ITM_JNL_CD, x4.AC_ITM_GRP_CD, x4.UNIT_CD,
			x4.LOT_NO, x4.SUBLOT_NO, x4.SNO1, x4.SNO2, x4.SNO3, x4.SNO4,
			x4.AC_SLIP_TYP, x4.AC_RSN_CD,
			x4.LOC_CD, x4.STR_LN_CD,
			x4.BP_CD, x4.STK_BP_CD,
			x4.PO_NO, x4.SLO_NO, x4.IV_NO,
			x4.OTHER_DPT_CD,
			x4.ASST_TYP,
			x4.REPURC_OBLI_FLG,
			m1.AREA_CD, m1.CNTRY_CD,
			x4.ITM_GRP_CD1, x4.ITM_GRP_CD2, x4.ITM_GRP_CD3, x4.ITM_GRP_CD4, x4.ITM_GRP_CD5,
			x4.ITM_GRP_CD6, x4.ITM_GRP_CD7, x4.ITM_GRP_CD8, x4.ITM_GRP_CD9, x4.ITM_GRP_CD10
		UNION ALL
		-- 投入（有償差益）
		SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
			x5.CALC_REC_TYP, x5.COST_IO_TYP,
			x5.WG_CD,
			x5.MNG_DPT_CD		DPT_CD1,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_CD) ITM_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_SUB1) ITM_SUB1,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_SUB2) ITM_SUB2,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_SUB3) ITM_SUB3,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_NM) ITM_NM,
			x5.ITM_JNL_CD, x5.AC_ITM_GRP_CD, x5.UNIT_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.LOT_NO) LOT_NO,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.SUBLOT_NO) SUBLOT_NO,
			x5.SNO1, x5.SNO2, x5.SNO3, x5.SNO4,
			x5.AC_SLIP_TYP, x5.AC_RSN_CD,
			x5.LOC_CD, x5.STR_LN_CD,
			x5.BP_CD, x5.STK_BP_CD,
			DECODE(L_PO_NO_IN_ONR_DIFF, G_OFF, NULL, t1.PO_NO) PO_NO,
			DECODE(L_SLO_NO_IN_ONR_DIFF, G_OFF, NULL, t1.SLO_NO) SLO_NO,
			DECODE(L_IV_NO_IN_ONR_DIFF, G_OFF, NULL, t1.IV_NO) IV_NO,
			t1.MNG_DPT_CD		DPT_CD2,
			x5.ASST_TYP,
			x5.REPURC_OBLI_FLG,
			SUM(x5.QTY)	QTY,
			NULL		TRD_GRP,
			SUM(x5.ACT_COST)	AMT,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_CD) TRD_ITM_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_SUB1) TRD_ITM_SUB1,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_SUB2) TRD_ITM_SUB2,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_SUB3) TRD_ITM_SUB3,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) TRD_ITM_NM,
			m1.ITM_JNL_CD		TRD_ITM_JNL_CD,
			m1.AC_ITM_GRP_CD	TRD_AC_ITM_GRP_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.LOT_NO) TRD_LOT_NO,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.SUBLOT_NO) TRD_SUBLOT_NO,
			t1.SNO1			TRD_SNO1,
			t1.SNO2			TRD_SNO2,
			t1.SNO3			TRD_SNO3,
			t1.SNO4			TRD_SNO4,
			m2.AREA_CD,
			m2.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD1) ITM_GRP_CD1,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD2) ITM_GRP_CD2,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD3) ITM_GRP_CD3,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD4) ITM_GRP_CD4,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD5) ITM_GRP_CD5,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD6) ITM_GRP_CD6,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD7) ITM_GRP_CD7,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD8) ITM_GRP_CD8,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD9) ITM_GRP_CD9,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD10) ITM_GRP_CD10,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD1) TRD_ITM_GRP_CD1,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD2) TRD_ITM_GRP_CD2,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD3) TRD_ITM_GRP_CD3,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD4) TRD_ITM_GRP_CD4,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD5) TRD_ITM_GRP_CD5,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD6) TRD_ITM_GRP_CD6,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD7) TRD_ITM_GRP_CD7,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD8) TRD_ITM_GRP_CD8,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD9) TRD_ITM_GRP_CD9,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD10) TRD_ITM_GRP_CD10
		FROM	(
			SELECT	t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.YM, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY,
				t1.ITM_MFG_INST_NO,
				t1.MFG_ACT_NO,
				t1.PAR_ITM_CD, t1.PAR_ITM_SUB1, t1.PAR_ITM_SUB2, t1.PAR_ITM_SUB3,
				t1.AMT - NVL(SUM(t2.ACT_COST), 0)	ACT_COST,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10
			FROM	(
				SELECT /*+INDEX(T MGT_ACC_TOP_ALL_IE01)*/
					t.CALC_GRP_CD, t.CALC_NO, t.TOP_REC_NO,
					t.CALC_REC_TYP, t.COST_IO_TYP,
					t.WG_CD, t.YM, t.MNG_DPT_CD,
					t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
					t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
					t.AC_RSN_CD,
					t.LOC_CD, t.STR_LN_CD,
					t.BP_CD, t.STK_BP_CD,
					t.OTHER_DPT_CD,
					t.ASST_TYP,
					t.REPURC_OBLI_FLG,
					t.QTY,
					NVL(t.SO_ACT_AMT, 0)	AMT,
					t.ITM_MFG_INST_NO,
					t.MFG_ACT_NO,
					t.PAR_ITM_CD,
					t.PAR_ITM_SUB1,
					t.PAR_ITM_SUB2,
					t.PAR_ITM_SUB3,
					C_AC_SLIP_IN_ONR_DIFF	AC_SLIP_TYP
				FROM	MGT_ACC_TOP t
				WHERE	0=0
				AND	t.CALC_NO = I_CALC_NO
				AND	t.CALC_GRP_CD = I_CALC_GRP_CD
				AND	t.CALC_REC_TYP = C_CALC_REC_INPT
				AND	t.AC_SLIP_TYP != C_AC_SLIP_IN_SS
				AND	(t.ASST_TYP = C_ASST_OTH OR t.REPURC_OBLI_FLG = '1')
				AND	L_INPT_ONR_FLG = '1'
				) t1,
				MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = t1.AC_SLIP_TYP
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			GROUP BY t1.TOP_REC_NO, t1.CALC_REC_TYP, t1.COST_IO_TYP,
				t1.WG_CD, t1.YM, t1.MNG_DPT_CD,
				t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
				NVL(m4.ITM_NM, m1.ITM_NM),
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_SLIP_TYP, t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD, t1.STK_BP_CD,
				t1.OTHER_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				t1.QTY, t1.AMT,
				t1.ITM_MFG_INST_NO,
				t1.MFG_ACT_NO,
				t1.PAR_ITM_CD, t1.PAR_ITM_SUB1, t1.PAR_ITM_SUB2, t1.PAR_ITM_SUB3,
				m1.ITM_GRP_CD1, m1.ITM_GRP_CD2, m1.ITM_GRP_CD3, m1.ITM_GRP_CD4, m1.ITM_GRP_CD5,
				m1.ITM_GRP_CD6, m1.ITM_GRP_CD7, m1.ITM_GRP_CD8, m1.ITM_GRP_CD9, m1.ITM_GRP_CD10
			) x5,
			MGT_ACC_TOP t1, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
		WHERE	0=0
		AND	t1.CALC_NO = I_CALC_NO
		AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
		AND	t1.ITM_CD = x5.PAR_ITM_CD
		AND	t1.ITM_SUB1 = x5.PAR_ITM_SUB1
		AND	t1.ITM_SUB2 = x5.PAR_ITM_SUB2
		AND	t1.ITM_SUB3 = x5.PAR_ITM_SUB3
		AND	t1.ITM_MFG_INST_NO = x5.ITM_MFG_INST_NO
		AND	t1.MFG_ACT_NO = x5.MFG_ACT_NO
		AND	t1.YM = x5.YM
		AND	t1.CALC_REC_TYP = C_CALC_REC_INST
		AND	t1.ITM_CD = m1.ITM_CD(+)
		AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.DEL_FLG(+) = '0'
		AND	m1.RELEASE_FLG(+) = '1'
		AND	t1.ITM_CD = m4.ITM_CD(+)
		AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
		AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
		AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
		AND	t1.SNO1 = m4.SNO1(+)
		AND	t1.SNO2 = m4.SNO2(+)
		AND	t1.SNO3 = m4.SNO3(+)
		AND	t1.SNO4 = m4.SNO4(+)
		AND	x5.BP_CD = m2.BP_CD(+)
		AND	m2.DEL_FLG(+) = '0'
		GROUP BY x5.CALC_REC_TYP, x5.COST_IO_TYP,
			x5.WG_CD, x5.MNG_DPT_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_CD),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_SUB1),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_SUB2),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.ITM_SUB3),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_NM),
			x5.ITM_JNL_CD, x5.AC_ITM_GRP_CD, x5.UNIT_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.LOT_NO),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, G_NULL_VAL, x5.SUBLOT_NO),
			x5.SNO1, x5.SNO2, x5.SNO3, x5.SNO4,
			x5.AC_SLIP_TYP, x5.AC_RSN_CD,
			x5.LOC_CD, x5.STR_LN_CD,
			x5.BP_CD, x5.STK_BP_CD,
			DECODE(L_PO_NO_IN_ONR_DIFF, G_OFF, NULL, t1.PO_NO),
			DECODE(L_SLO_NO_IN_ONR_DIFF, G_OFF, NULL, t1.SLO_NO),
			DECODE(L_IV_NO_IN_ONR_DIFF, G_OFF, NULL, t1.IV_NO),
			t1.MNG_DPT_CD,
			x5.ASST_TYP,
			x5.REPURC_OBLI_FLG,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_CD),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_SUB1),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_SUB2),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.ITM_SUB3),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)),
			m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.LOT_NO),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, t1.SUBLOT_NO),
			t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
			m2.AREA_CD, m2.CNTRY_CD,
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD1),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD2),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD3),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD4),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD5),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD6),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD7),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD8),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD9),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, x5.ITM_GRP_CD10),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD1),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD2),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD3),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD4),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD5),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD6),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD7),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD8),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD9),
			DECODE(L_ITM_SUM_IN_ONR_DIFF, G_ON, NULL, m1.ITM_GRP_CD10)
		UNION ALL
		-- 評価損
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x6.WG_CD,
			x6.MNG_DPT_CD		DPT_CD1,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_CD) ITM_CD,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_SUB1) ITM_SUB1,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_SUB2) ITM_SUB2,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_SUB3) ITM_SUB3,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
			m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.LOT_NO) LOT_NO,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.SUBLOT_NO) SUBLOT_NO,
			x6.SNO1, x6.SNO2, x6.SNO3, x6.SNO4,
			C_AC_SLIP_EOM_STK_ASM_MIS		AC_SLIP_TYP,
			m3.AC_RSN_CD	AC_RSN_CD,
			NULL	LOC_CD,
			NULL	STR_LN_CD,
			x6.SPPL_CD	BP_CD,
			x6.SPPL_CD	STK_BP_CD,
			NULL	PO_NO,
			NULL	SLO_NO,
			NULL	IV_NO,
			NULL	DPT_CD2,
			x6.ASST_TYP,
			'0'	REPURC_OBLI_FLG,
			0	QTY,
			NULL	TRD_GRP,
			SUM(x6.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			m2.AREA_CD,
			m2.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	MGT_STK_LOSS x6, MAM_ITM_SRCH m1, MAM_BP m2, MAM_STK_EVAL m3, MAM_SUNDRY_ITM m4
		WHERE	0=0
		AND	x6.CALC_NO = I_CALC_NO
		AND	x6.CALC_GRP_CD = I_CALC_GRP_CD
		AND	x6.ITM_CD = m1.ITM_CD(+)
		AND	x6.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	x6.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	x6.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.DEL_FLG(+) = '0'
		AND	m1.RELEASE_FLG(+) = '1'
		AND	x6.ITM_CD = m4.ITM_CD(+)
		AND	x6.ITM_SUB1 = m4.ITM_SUB1(+)
		AND	x6.ITM_SUB2 = m4.ITM_SUB2(+)
		AND	x6.ITM_SUB3 = m4.ITM_SUB3(+)
		AND	x6.SNO1 = m4.SNO1(+)
		AND	x6.SNO2 = m4.SNO2(+)
		AND	x6.SNO3 = m4.SNO3(+)
		AND	x6.SNO4 = m4.SNO4(+)
		AND	x6.SPPL_CD = m2.BP_CD(+)
		AND	m2.DEL_FLG(+) = '0'
		AND	x6.STK_EVAL_CD = m3.STK_EVAL_CD(+)
		AND	m3.DEL_FLG(+) = '0'
		AND	L_STK_LOSS_FLG = '1'
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_AC_OUT m
				WHERE	0=0
				AND	m.CALC_GRP_CD = x6.CALC_GRP_CD
				AND	m.AC_SLIP_TYP = C_AC_SLIP_EOM_STK_ASM_MIS
				AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
				AND	m.ST_DT <= L_END_DT
				AND	m.END_DT >= L_END_DT
				)
		GROUP BY x6.WG_CD, x6.MNG_DPT_CD,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_CD),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_SUB1),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_SUB2),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.ITM_SUB3),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)),
			m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.LOT_NO),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, G_NULL_VAL, x6.SUBLOT_NO),
			x6.SNO1, x6.SNO2, x6.SNO3, x6.SNO4,
			m3.AC_RSN_CD, x6.SPPL_CD, x6.ASST_TYP,
			m2.AREA_CD, m2.CNTRY_CD,
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD1),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD2),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD3),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD4),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD5),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD6),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD7),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD8),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD9),
			DECODE(L_ITM_SUM_EOM_STK_ASM_MIS, G_ON, NULL, m1.ITM_GRP_CD10)
		UNION ALL
		-- 月初在庫評価替差異
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			t1.WG_CD,
			t1.MNG_DPT_CD		DPT_CD1,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
			m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
			t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
			C_AC_SLIP_STK_ASM_DIFF	AC_SLIP_TYP,
			NULL	AC_RSN_CD,
			NULL	LOC_CD,
			NULL	STR_LN_CD,
			t1.BP_CD,
			t1.BP_CD	STK_BP_CD,
			NULL	PO_NO,
			NULL	SLO_NO,
			NULL	IV_NO,
			NULL	DPT_CD2,
			t1.ASST_TYP,
			'0'	REPURC_OBLI_FLG,
			0	QTY,
			NULL	TRD_GRP,
			SUM(t2.DIFF_AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			NULL	AREA_CD,
			NULL	CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL ALC_AC_CD,
			NULL EXPNS_CD,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	MGT_ST_STK t1, MGT_ST_STK_DIFF t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
		WHERE	0=0
		AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
		AND	t1.YM = I_YM
		AND	t1.ASST_TYP IN (C_ASST_PROD, C_ASST_SLS)
		AND	t1.ST_STK_KEY = t2.ST_STK_KEY
		AND	t1.ITM_CD = m1.ITM_CD(+)
		AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.DEL_FLG(+) = '0'
		AND	m1.RELEASE_FLG(+) = '1'
		AND	t1.ITM_CD = m4.ITM_CD(+)
		AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
		AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
		AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
		AND	t1.SNO1 = m4.SNO1(+)
		AND	t1.SNO2 = m4.SNO2(+)
		AND	t1.SNO3 = m4.SNO3(+)
		AND	t1.SNO4 = m4.SNO4(+)
		AND	t1.BP_CD = m2.BP_CD(+)
		AND	m2.DEL_FLG(+) = '0'
		AND	L_ST_DIFF_FLG = '1'
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_AC_OUT m
				WHERE	0=0
				AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
				AND	m.AC_SLIP_TYP = C_AC_SLIP_STK_ASM_DIFF
				AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
				AND	m.ST_DT <= L_END_DT
				AND	m.END_DT >= L_END_DT
				)
		GROUP BY t1.WG_CD, t1.MNG_DPT_CD,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_CD),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB1),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB2),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.ITM_SUB3),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)),
			m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.LOT_NO),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, G_NULL_VAL, t1.SUBLOT_NO),
			t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
			t1.BP_CD, t1.ASST_TYP,
			m2.AREA_CD, m2.CNTRY_CD,
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD1),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD2),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD3),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD4),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD5),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD6),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD7),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD8),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD9),
			DECODE(L_ITM_SUM_STK_ASM_DIFF, G_ON, NULL, m1.ITM_GRP_CD10)
		UNION ALL
		-- 配賦原価
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			t2.WG_CD,
			t2.DPT_CD	DPT_CD1,
			t2.ITM_CD, t2.ITM_SUB1, t2.ITM_SUB2, t2.ITM_SUB3, t2.ITM_NM,
			t2.ITM_JNL_CD, t2.AC_ITM_GRP_CD, t2.UNIT_CD,
			t2.LOT_NO, t2.SUBLOT_NO, t2.SNO1, t2.SNO2, t2.SNO3, t2.SNO4,
			C_AC_SLIP_ITM_ALC	AC_SLIP_TYP,
			t2.AC_RSN_CD,
			t2.LOC_CD, t2.STR_LN_CD,
			t2.BP_CD,
			NULL	STK_BP_CD,
			t2.PO_NO, t2.SLO_NO, t2.IV_NO,
			t2.MNG_DPT_CD	DPT_CD2,
			t2.ASST_TYP,
			'0'	REPURC_OBLI_FLG,
			0	QTY,
			NULL	TRD_GRP,
			SUM(t2.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			m1.AREA_CD,
			m1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			t2.ALC_AC_CD,
			t2.EXPNS_CD,
			t2.ITM_GRP_CD1, t2.ITM_GRP_CD2, t2.ITM_GRP_CD3, t2.ITM_GRP_CD4, t2.ITM_GRP_CD5,
			t2.ITM_GRP_CD6, t2.ITM_GRP_CD7, t2.ITM_GRP_CD8, t2.ITM_GRP_CD9, t2.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			SELECT t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_ITM_ALC, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_ITM_ALC, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_ITM_ALC, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.DPT_CD,
				t1.ASST_TYP,
				SUM(t1.ALC_AMT + t1.ADJ_AMT)	AMT,
				t1.ALC_AC_CD, t1.EXPNS_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	(
				SELECT
					t1.CALC_GRP_CD,
					t1.WG_CD, t1.MNG_DPT_CD,
					t1.ITM_CD, t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3,
					t1.LOT_NO, t1.SUBLOT_NO, t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
					t1.AC_RSN_CD,
					t1.LOC_CD, t1.STR_LN_CD,
					t1.BP_CD,
					t1.PO_NO, t1.SLO_NO, t1.IV_NO,
					t1.ASST_TYP,
					t1.ALC_AMT, t1.ADJ_AMT,
					t2.ALC_AC_CD, t2.DPT_CD, t2.EXPNS_CD
				FROM	MGT_ALC_CALC_RATE t2, MGT_ALC_CALC_DTL t1
				WHERE	0=0
				AND	t2.CALC_NO = I_CALC_NO
				AND	t2.CALC_GRP_CD = I_CALC_GRP_CD
				AND	t2.DPT_CD IS NOT NULL
				AND	t1.CALC_NO = t2.CALC_NO
				AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
				AND	t1.ALC_GRP_ID = t2.ALC_GRP_ID
				AND	L_ITM_ALC_FLG = '1'
				AND	EXISTS (
						SELECT	'X'
						FROM	MAM_ALC_AC m
						WHERE	0=0
						AND	m.ALC_AC_CD = t2.ALC_AC_CD
						AND	m.NOT_ITM_ALC_AC_FLG = '0'
						AND	m.DEL_FLG = '0'
					)
				) t1,
				MAM_ITM_SRCH m1, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_ITM_ALC
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
				)
			GROUP BY t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_CD),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_SUB1),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_SUB2),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.ITM_SUB3),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)),
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.LOT_NO),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, G_NULL_VAL, t1.SUBLOT_NO),
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				t1.PO_NO, t1.SLO_NO, t1.IV_NO,
				t1.ASST_TYP,
				t1.ALC_AC_CD, t1.DPT_CD, t1.EXPNS_CD,
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD1),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD2),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD3),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD4),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD5),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD6),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD7),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD8),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD9),
				DECODE(L_ITM_SUM_ITM_ALC, G_ON, NULL, m1.ITM_GRP_CD10)
			) t2,
			MAM_BP m1
		WHERE	0=0
		AND	t2.BP_CD = m1.BP_CD(+)
		AND	m1.DEL_FLG(+) = '0'
		GROUP BY t2.WG_CD, t2.MNG_DPT_CD,
			t2.ITM_CD, t2.ITM_SUB1, t2.ITM_SUB2, t2.ITM_SUB3, t2.ITM_NM,
			t2.ITM_JNL_CD, t2.AC_ITM_GRP_CD, t2.UNIT_CD,
			t2.LOT_NO, t2.SUBLOT_NO, t2.SNO1, t2.SNO2, t2.SNO3, t2.SNO4,
			t2.AC_RSN_CD,
			t2.LOC_CD, t2.STR_LN_CD,
			t2.BP_CD,
			t2.PO_NO, t2.SLO_NO, t2.IV_NO,
			t2.ASST_TYP,
			t2.ALC_AC_CD, t2.DPT_CD, t2.EXPNS_CD,
			m1.AREA_CD, m1.CNTRY_CD,
			t2.ITM_GRP_CD1, t2.ITM_GRP_CD2, t2.ITM_GRP_CD3, t2.ITM_GRP_CD4, t2.ITM_GRP_CD5,
			t2.ITM_GRP_CD6, t2.ITM_GRP_CD7, t2.ITM_GRP_CD8, t2.ITM_GRP_CD9, t2.ITM_GRP_CD10
		UNION ALL
		-- 受入価格差異（合計）/（単価差異）/（レート差異）
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.MNG_DPT_CD	DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			NULL	LOC_CD,
			NULL	STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.ALC_DPT_CD	DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			0		QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL	ALC_AC_CD,
			NULL	EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			-- 受入価格差異（合計）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_IO_SUM, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_IO_SUM, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_IO_SUM, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ALC_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t1.STD_AMT, 0) - NVL(t1.AMT, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_IO_SUM		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_IO_SUM, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_IO_SUM_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_PURC
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_IO_SUM
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 受入価格差異（単価差異）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_IO_PRI, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_IO_PRI, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_IO_PRI, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ALC_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t1.UPRI_DIFF, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_IO_PRI		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_IO_PRI, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_IO_PRI_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_PURC
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_IO_PRI
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 受入価格差異（レート差異）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_IO_RATE, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_IO_RATE, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_IO_RATE, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ALC_DPT_CD,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t1.RATE_DIFF, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_IO_RATE		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_IO_RATE, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_IO_RATE_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_PURC
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_IO_RATE
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			) x1
		GROUP BY x1.WG_CD, x1.MNG_DPT_CD,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.ALC_DPT_CD,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10
		UNION ALL
		-- 数量差異（親）/ 払出価格差異（親）
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.MNG_DPT_CD	DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD,
			x1.STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.MNG_DPT_CD	DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			0		QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL	ALC_AC_CD,
			NULL	EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			-- 数量差異（親）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_QT_PAR, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_QT_PAR, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_QT_PAR, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t2.DIFF_QTY, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_QT_PAR		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_QT_PAR, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_QT_PAR_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_QT_PAR
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 払出価格差異（親）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_PR_PAR, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_PR_PAR, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_PR_PAR, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t3.DIFF_UP, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_PR_PAR		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_PR_PAR, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_INPT T2, MGT_ACC_COST T3, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_PR_PAR_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO
			AND	t2.LVL = 1
			AND	T2.AC_SLIP_TYP <> MAC_AC_SLIP_TYP.IN_SS
			AND	T2.CALC_NO = T3.CALC_NO(+)
			AND	T2.CALC_GRP_CD = T3.CALC_GRP_CD(+)
			AND	T2.INPT_REC_NO = T3.SML_INPT_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_PR_PAR
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			) x1
		GROUP BY x1.WG_CD, x1.MNG_DPT_CD,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10
		UNION ALL
		-- 数量差異（子）/ 払出価格差異（子）
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD,
			x1.STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			0		QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			x1.TRD_ITM_CD, x1.TRD_ITM_SUB1, x1.TRD_ITM_SUB2, x1.TRD_ITM_SUB3, x1.TRD_ITM_NM,
			x1.TRD_ITM_JNL_CD, x1.TRD_AC_ITM_GRP_CD,
			x1.TRD_LOT_NO, x1.TRD_SUBLOT_NO, x1.TRD_SNO1, x1.TRD_SNO2, x1.TRD_SNO3, x1.TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL	ALC_AC_CD,
			NULL	EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			x1.TRD_ITM_GRP_CD1, x1.TRD_ITM_GRP_CD2, x1.TRD_ITM_GRP_CD3, x1.TRD_ITM_GRP_CD4, x1.TRD_ITM_GRP_CD5,
			x1.TRD_ITM_GRP_CD6, x1.TRD_ITM_GRP_CD7, x1.TRD_ITM_GRP_CD8, x1.TRD_ITM_GRP_CD9, x1.TRD_ITM_GRP_CD10
		FROM	(
			-- 数量差異（子）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD,
				t1.MNG_DPT_CD	DPT_CD1,
				t2.MNG_DPT_CD	DPT_CD2,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t2.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t2.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t2.SUBLOT_NO) SUBLOT_NO,
				t2.SNO1, t2.SNO2, t2.SNO3, t2.SNO4,
				t2.AC_RSN_CD,
				t2.LOC_CD, t2.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_QT_CHD, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_QT_CHD, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_QT_CHD, G_OFF, NULL, t1.IV_NO) IV_NO,
				t2.ASST_TYP,
				t2.REPURC_OBLI_FLG,
				NVL(t3.DIFF_QTY, 0)	AMT,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t1.ITM_CD) TRD_ITM_CD,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB1) TRD_ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB2) TRD_ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB3) TRD_ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, NVL(m6.ITM_NM, m5.ITM_NM)) TRD_ITM_NM,
				m5.ITM_JNL_CD TRD_ITM_JNL_CD,
				m5.AC_ITM_GRP_CD TRD_AC_ITM_GRP_CD,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t1.LOT_NO) TRD_LOT_NO,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, G_NULL_VAL, t1.SUBLOT_NO) TRD_SUBLOT_NO,
				t1.SNO1 TRD_SNO1,
				t1.SNO2 TRD_SNO2,
				t1.SNO3 TRD_SNO3,
				t1.SNO4 TRD_SNO4,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_QT_CHD		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD1) TRD_ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD2) TRD_ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD3) TRD_ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD4) TRD_ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD5) TRD_ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD6) TRD_ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD7) TRD_ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD8) TRD_ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD9) TRD_ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_QT_CHD, G_ON, NULL, m5.ITM_GRP_CD10) TRD_ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_INPT T2, MGT_ACC_COST T3,
					MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4, MAM_ITM_SRCH m5, MAM_SUNDRY_ITM m6
			WHERE	0=0
			AND	L_DIFF_QT_CHD_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO
			AND	t2.LVL = 1
			AND T2.CALC_NO = T3.CALC_NO(+)
			AND T2.CALC_GRP_CD = T3.CALC_GRP_CD(+)
			AND T2.INPT_REC_NO = T3.SML_INPT_REC_NO(+)
			AND	t2.ITM_CD = m1.ITM_CD(+)
			AND	t2.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t2.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t2.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t2.ITM_CD = m4.ITM_CD(+)
			AND	t2.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t2.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t2.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t2.SNO1 = m4.SNO1(+)
			AND	t2.SNO2 = m4.SNO2(+)
			AND	t2.SNO3 = m4.SNO3(+)
			AND	t2.SNO4 = m4.SNO4(+)
			AND	t1.ITM_CD = m5.ITM_CD(+)
			AND	t1.ITM_SUB1 = m5.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m5.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m5.ITM_SUB3(+)
			AND	m5.DEL_FLG(+) = '0'
			AND	m5.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m6.ITM_CD(+)
			AND	t1.ITM_SUB1 = m6.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m6.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m6.ITM_SUB3(+)
			AND	t1.SNO1 = m6.SNO1(+)
			AND	t1.SNO2 = m6.SNO2(+)
			AND	t1.SNO3 = m6.SNO3(+)
			AND	t1.SNO4 = m6.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_QT_CHD
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 払出価格差異（子）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD,
				t1.MNG_DPT_CD	DPT_CD1,
				t2.MNG_DPT_CD	DPT_CD2,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t2.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t2.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t2.SUBLOT_NO) SUBLOT_NO,
				t2.SNO1, t2.SNO2, t2.SNO3, t2.SNO4,
				t2.AC_RSN_CD,
				t2.LOC_CD, t2.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_PR_CHD, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_PR_CHD, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_PR_CHD, G_OFF, NULL, t1.IV_NO) IV_NO,
				t2.ASST_TYP,
				t2.REPURC_OBLI_FLG,
				NVL(t3.DIFF_UP, 0)	AMT,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t1.ITM_CD) TRD_ITM_CD,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB1) TRD_ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB2) TRD_ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB3) TRD_ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, NVL(m6.ITM_NM, m5.ITM_NM)) TRD_ITM_NM,
				m5.ITM_JNL_CD TRD_ITM_JNL_CD,
				m5.AC_ITM_GRP_CD TRD_AC_ITM_GRP_CD,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t1.LOT_NO) TRD_LOT_NO,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, G_NULL_VAL, t1.SUBLOT_NO) TRD_SUBLOT_NO,
				t1.SNO1 TRD_SNO1,
				t1.SNO2 TRD_SNO2,
				t1.SNO3 TRD_SNO3,
				t1.SNO4 TRD_SNO4,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_PR_CHD		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD1) TRD_ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD2) TRD_ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD3) TRD_ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD4) TRD_ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD5) TRD_ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD6) TRD_ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD7) TRD_ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD8) TRD_ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD9) TRD_ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_PR_CHD, G_ON, NULL, m5.ITM_GRP_CD10) TRD_ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_INPT T2, MGT_ACC_COST T3,
					MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4, MAM_ITM_SRCH m5, MAM_SUNDRY_ITM m6
			WHERE	0=0
			AND	L_DIFF_PR_CHD_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO
			AND	t2.LVL = 1
			AND	T2.AC_SLIP_TYP <> MAC_AC_SLIP_TYP.IN_SS
			AND	T2.CALC_NO = T3.CALC_NO(+)
			AND	T2.CALC_GRP_CD = T3.CALC_GRP_CD(+)
			AND	T2.INPT_REC_NO = T3.SML_INPT_REC_NO(+)
			AND	t2.ITM_CD = m1.ITM_CD(+)
			AND	t2.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t2.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t2.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t2.ITM_CD = m4.ITM_CD(+)
			AND	t2.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t2.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t2.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t2.SNO1 = m4.SNO1(+)
			AND	t2.SNO2 = m4.SNO2(+)
			AND	t2.SNO3 = m4.SNO3(+)
			AND	t2.SNO4 = m4.SNO4(+)
			AND	t1.ITM_CD = m5.ITM_CD(+)
			AND	t1.ITM_SUB1 = m5.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m5.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m5.ITM_SUB3(+)
			AND	m5.DEL_FLG(+) = '0'
			AND	m5.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m6.ITM_CD(+)
			AND	t1.ITM_SUB1 = m6.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m6.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m6.ITM_SUB3(+)
			AND	t1.SNO1 = m6.SNO1(+)
			AND	t1.SNO2 = m6.SNO2(+)
			AND	t1.SNO3 = m6.SNO3(+)
			AND	t1.SNO4 = m6.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_PR_CHD
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			) x1
		GROUP BY x1.WG_CD, x1.DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.DPT_CD2, x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.TRD_ITM_CD, x1.TRD_ITM_SUB1, x1.TRD_ITM_SUB2, x1.TRD_ITM_SUB3, x1.TRD_ITM_NM,
			x1.TRD_ITM_JNL_CD, x1.TRD_AC_ITM_GRP_CD,
			x1.TRD_LOT_NO, x1.TRD_SUBLOT_NO, x1.TRD_SNO1, x1.TRD_SNO2, x1.TRD_SNO3, x1.TRD_SNO4,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			x1.TRD_ITM_GRP_CD1, x1.TRD_ITM_GRP_CD2, x1.TRD_ITM_GRP_CD3, x1.TRD_ITM_GRP_CD4, x1.TRD_ITM_GRP_CD5,
			x1.TRD_ITM_GRP_CD6, x1.TRD_ITM_GRP_CD7, x1.TRD_ITM_GRP_CD8, x1.TRD_ITM_GRP_CD9, x1.TRD_ITM_GRP_CD10
		UNION ALL
		-- 工数差異 / 実績差異１～５ / 配賦率差異（品目）
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.MNG_DPT_CD	DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD,
			x1.STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.MNG_DPT_CD	DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			0		QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL	ALC_AC_CD,
			x1.EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			-- 工数差異
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_WK, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_WK, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_WK, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t2.DIFF_WK, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_WK		AC_SLIP_TYP,
				t2.EXPNS_CD,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_WK, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_WK_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_WK
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 実績差異１
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_ACT1, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_ACT1, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_ACT1, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t2.DIFF_A, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_ACT1		AC_SLIP_TYP,
				t2.EXPNS_CD,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_ACT1, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_ACT1_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP IN (C_CALC_REC_INST, C_CALC_REC_PURC)
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT1
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 実績差異２
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_ACT2, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_ACT2, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_ACT2, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t2.DIFF_B, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_ACT2		AC_SLIP_TYP,
				t2.EXPNS_CD,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_ACT2, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_ACT2_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP IN (C_CALC_REC_INST, C_CALC_REC_PURC)
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT2
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			UNION ALL
			-- 実績差異３
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_ACT3, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_ACT3, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_ACT3, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t2.DIFF_C, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_ACT3		AC_SLIP_TYP,
				t2.EXPNS_CD,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_ACT3, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
