				DECODE(L_ITM_SUM_DIFF_ACT4, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_ACT4, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
