				DECODE(L_ITM_SUM_DIFF_ACT4, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_ACT4, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
