			UNION ALL
			-- 実績差異５
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
