				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_ACT5, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_ACT5_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP IN (C_CALC_REC_INST, C_CALC_REC_PURC)
