					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_ACT5
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
