				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
