				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_RATE_ITM		AC_SLIP_TYP,
				t2.EXPNS_CD,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
