				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_RATE_ITM, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
