			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			-- 外注単価差異（合計）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
