				DECODE(L_ITM_SUM_DIFF_SS_PAR, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_SS_PAR, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_SS_PAR, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_INPT T2, MGT_ACC_COST T3, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_SS_PAR_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO
			AND	t2.LVL = 1
			AND	t2.AC_SLIP_TYP = C_AC_SLIP_IN_SS
			AND	t2.ASST_TYP = C_ASST_OTH
			AND T2.CALC_NO = T3.CALC_NO(+)
			AND T2.CALC_GRP_CD = T3.CALC_GRP_CD(+)
			AND T2.INPT_REC_NO = T3.SML_INPT_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_SS_PAR
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			) x1
		GROUP BY x1.WG_CD, x1.MNG_DPT_CD,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10
		UNION ALL
		-- 自給単価差異（子）
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD,
			x1.STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			0		QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			x1.TRD_ITM_CD, x1.TRD_ITM_SUB1, x1.TRD_ITM_SUB2, x1.TRD_ITM_SUB3, x1.TRD_ITM_NM,
			x1.TRD_ITM_JNL_CD, x1.TRD_AC_ITM_GRP_CD,
			x1.TRD_LOT_NO, x1.TRD_SUBLOT_NO, x1.TRD_SNO1, x1.TRD_SNO2, x1.TRD_SNO3, x1.TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL	ALC_AC_CD,
			NULL	EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			x1.TRD_ITM_GRP_CD1, x1.TRD_ITM_GRP_CD2, x1.TRD_ITM_GRP_CD3, x1.TRD_ITM_GRP_CD4, x1.TRD_ITM_GRP_CD5,
			x1.TRD_ITM_GRP_CD6, x1.TRD_ITM_GRP_CD7, x1.TRD_ITM_GRP_CD8, x1.TRD_ITM_GRP_CD9, x1.TRD_ITM_GRP_CD10
		FROM	(
			-- 自給単価差異（子）
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD,
				t1.MNG_DPT_CD	DPT_CD1,
				t2.MNG_DPT_CD	DPT_CD2,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t2.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t2.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t2.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t2.SUBLOT_NO) SUBLOT_NO,
				t2.SNO1, t2.SNO2, t2.SNO3, t2.SNO4,
				t2.AC_RSN_CD,
				t2.LOC_CD, t2.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_SS_CHD, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_SS_CHD, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_SS_CHD, G_OFF, NULL, t1.IV_NO) IV_NO,
				t2.ASST_TYP,
				t2.REPURC_OBLI_FLG,
				NVL(t3.DIFF_UP, 0)	AMT,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t1.ITM_CD) TRD_ITM_CD,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB1) TRD_ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB2) TRD_ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t1.ITM_SUB3) TRD_ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, NVL(m6.ITM_NM, m5.ITM_NM)) TRD_ITM_NM,
				m5.ITM_JNL_CD TRD_ITM_JNL_CD,
				m5.AC_ITM_GRP_CD TRD_AC_ITM_GRP_CD,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t1.LOT_NO) TRD_LOT_NO,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, G_NULL_VAL, t1.SUBLOT_NO) TRD_SUBLOT_NO,
				t1.SNO1 TRD_SNO1,
				t1.SNO2 TRD_SNO2,
				t1.SNO3 TRD_SNO3,
				t1.SNO4 TRD_SNO4,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_SS_CHD		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD1) TRD_ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD2) TRD_ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD3) TRD_ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD4) TRD_ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD5) TRD_ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD6) TRD_ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD7) TRD_ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD8) TRD_ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD9) TRD_ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_SS_CHD, G_ON, NULL, m5.ITM_GRP_CD10) TRD_ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_INPT T2, MGT_ACC_COST T3,
					MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4, MAM_ITM_SRCH m5, MAM_SUNDRY_ITM m6
			WHERE	0=0
			AND	L_DIFF_SS_CHD_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP = C_CALC_REC_INST
			AND	t1.CALC_NO = t2.CALC_NO
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO
			AND	t2.LVL = 1
			AND	t2.AC_SLIP_TYP = C_AC_SLIP_IN_SS
			AND	t2.ASST_TYP = C_ASST_OTH
			AND T2.CALC_NO = T3.CALC_NO(+)
			AND T2.CALC_GRP_CD = T3.CALC_GRP_CD(+)
			AND T2.INPT_REC_NO = T3.SML_INPT_REC_NO(+)
			AND	t2.ITM_CD = m1.ITM_CD(+)
			AND	t2.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t2.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t2.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t2.ITM_CD = m4.ITM_CD(+)
			AND	t2.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t2.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t2.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t2.SNO1 = m4.SNO1(+)
			AND	t2.SNO2 = m4.SNO2(+)
			AND	t2.SNO3 = m4.SNO3(+)
			AND	t2.SNO4 = m4.SNO4(+)
			AND	t1.ITM_CD = m5.ITM_CD(+)
			AND	t1.ITM_SUB1 = m5.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m5.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m5.ITM_SUB3(+)
			AND	m5.DEL_FLG(+) = '0'
			AND	m5.RELEASE_FLG(+) = '1'
			AND	t1.ITM_CD = m6.ITM_CD(+)
			AND	t1.ITM_SUB1 = m6.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m6.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m6.ITM_SUB3(+)
			AND	t1.SNO1 = m6.SNO1(+)
			AND	t1.SNO2 = m6.SNO2(+)
			AND	t1.SNO3 = m6.SNO3(+)
			AND	t1.SNO4 = m6.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_SS_CHD
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			) x1
		GROUP BY x1.WG_CD, x1.DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.DPT_CD2, x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.TRD_ITM_CD, x1.TRD_ITM_SUB1, x1.TRD_ITM_SUB2, x1.TRD_ITM_SUB3, x1.TRD_ITM_NM,
			x1.TRD_ITM_JNL_CD, x1.TRD_AC_ITM_GRP_CD,
			x1.TRD_LOT_NO, x1.TRD_SUBLOT_NO, x1.TRD_SNO1, x1.TRD_SNO2, x1.TRD_SNO3, x1.TRD_SNO4,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			x1.TRD_ITM_GRP_CD1, x1.TRD_ITM_GRP_CD2, x1.TRD_ITM_GRP_CD3, x1.TRD_ITM_GRP_CD4, x1.TRD_ITM_GRP_CD5,
			x1.TRD_ITM_GRP_CD6, x1.TRD_ITM_GRP_CD7, x1.TRD_ITM_GRP_CD8, x1.TRD_ITM_GRP_CD9, x1.TRD_ITM_GRP_CD10
		UNION ALL
		-- 配賦率差異（配賦科目）
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.DPT_CD	DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP,
			NULL	AC_RSN_CD,
			x1.LOC_CD,
			NULL	STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.DPT_CD	DPT_CD2,
			NULL	ASST_TYP,
			'0'	REPURC_OBLI_FLG,
			0	QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			x1.ALC_AC_CD,
			x1.EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			SELECT
				t1.WG_CD, t1.DPT_CD,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, G_NULL_VAL, NVL(t1.ITM_CD, G_NULL_VAL)) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, G_NULL_VAL, NVL(t1.ITM_SUB1, G_NULL_VAL)) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, G_NULL_VAL, NVL(t1.ITM_SUB2, G_NULL_VAL)) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, G_NULL_VAL, NVL(t1.ITM_SUB3, G_NULL_VAL)) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				NVL(m1.ITM_JNL_CD, G_NULL_VAL) ITM_JNL_CD,
				m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.LOC_CD, t1.BP_CD,
				DECODE(L_PO_NO_DIFF_RATE_ALC, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_RATE_ALC, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_RATE_ALC, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.AMT - (t1.ALC_AMT + t1.TRD_ALC_AMT)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_RATE_ALC		AC_SLIP_TYP,
				t1.ALC_AC_CD, t1.EXPNS_CD,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_RATE_ALC, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ALC_CALC_RATE t1, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_RATE_ALC_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.DPT_CD IS NOT NULL
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_RATE_ALC
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			AND	EXISTS (
					SELECT	'X'
					FROM	MAM_ALC_AC m
					WHERE	0=0
					AND	m.ALC_AC_CD = t1.ALC_AC_CD
					AND	m.NOT_ALC_RATE_AC_FLG = '0'
					AND	m.DEL_FLG = '0'
					)
			) x1
		GROUP BY x1.WG_CD, x1.DPT_CD,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP,
			x1.LOC_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.ALC_AC_CD, x1.EXPNS_CD,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10
		UNION ALL
		-- 標準調整差異
		SELECT	NULL	CALC_REC_TYP,
			NULL	COST_IO_TYP,
			x1.WG_CD,
			x1.MNG_DPT_CD	DPT_CD1,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD,
			x1.STR_LN_CD,
			x1.BP_CD,
			NULL	STK_BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.MNG_DPT_CD	DPT_CD2,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			0		QTY,
			NULL	TRD_GRP,
			SUM(x1.AMT)	AMT,
			NULL	TRD_ITM_CD,
			NULL	TRD_ITM_SUB1,
			NULL	TRD_ITM_SUB2,
			NULL	TRD_ITM_SUB3,
			NULL	TRD_ITM_NM,
			NULL	TRD_ITM_JNL_CD,
			NULL	TRD_AC_ITM_GRP_CD,
			NULL	TRD_LOT_NO,
			NULL	TRD_SUBLOT_NO,
			NULL	TRD_SNO1,
			NULL	TRD_SNO2,
			NULL	TRD_SNO3,
			NULL	TRD_SNO4,
			x1.AREA_CD,
			x1.CNTRY_CD,
			NULL	SLS_DPT_CD,
			NULL	USR_CD,
			NULL	ALC_AC_CD,
			NULL	EXPNS_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM	(
			-- 標準調整差異
			SELECT /*+INDEX(T1 MGT_ACC_TOP_ALL_IE01)*/
				t1.WG_CD, t1.MNG_DPT_CD,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, G_NULL_VAL, t1.ITM_CD) ITM_CD,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, G_NULL_VAL, t1.ITM_SUB1) ITM_SUB1,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, G_NULL_VAL, t1.ITM_SUB2) ITM_SUB2,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, G_NULL_VAL, t1.ITM_SUB3) ITM_SUB3,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, NVL(m4.ITM_NM, m1.ITM_NM)) ITM_NM,
				m1.ITM_JNL_CD, m1.AC_ITM_GRP_CD, m1.UNIT_CD,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, G_NULL_VAL, t1.LOT_NO) LOT_NO,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, G_NULL_VAL, t1.SUBLOT_NO) SUBLOT_NO,
				t1.SNO1, t1.SNO2, t1.SNO3, t1.SNO4,
				t1.AC_RSN_CD,
				t1.LOC_CD, t1.STR_LN_CD,
				t1.BP_CD,
				DECODE(L_PO_NO_DIFF_STD_ADJ, G_OFF, NULL, t1.PO_NO) PO_NO,
				DECODE(L_SLO_NO_DIFF_STD_ADJ, G_OFF, NULL, t1.SLO_NO) SLO_NO,
				DECODE(L_IV_NO_DIFF_STD_ADJ, G_OFF, NULL, t1.IV_NO) IV_NO,
				t1.ASST_TYP,
				t1.REPURC_OBLI_FLG,
				NVL(t2.DIFF_STD, 0)	AMT,
				m2.AREA_CD,
				m2.CNTRY_CD,
				C_AC_SLIP_DIFF_STD_ADJ		AC_SLIP_TYP,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD1) ITM_GRP_CD1,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD2) ITM_GRP_CD2,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD3) ITM_GRP_CD3,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD4) ITM_GRP_CD4,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD5) ITM_GRP_CD5,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD6) ITM_GRP_CD6,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD7) ITM_GRP_CD7,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD8) ITM_GRP_CD8,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD9) ITM_GRP_CD9,
				DECODE(L_ITM_SUM_DIFF_STD_ADJ, G_ON, NULL, m1.ITM_GRP_CD10) ITM_GRP_CD10
			FROM	MGT_ACC_TOP t1, MGT_ACC_SML_COST t2, MAM_ITM_SRCH m1, MAM_BP m2, MAM_SUNDRY_ITM m4
			WHERE	0=0
			AND	L_DIFF_STD_ADJ_FLG = '1'
			AND	t1.CALC_NO = I_CALC_NO
			AND	t1.CALC_GRP_CD = I_CALC_GRP_CD
			AND	t1.CALC_REC_TYP IN (C_CALC_REC_INST, C_CALC_REC_PURC)
			AND	t1.CALC_NO = t2.CALC_NO(+)
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD(+)
			AND	t1.TOP_REC_NO = t2.TOP_REC_NO(+)
			AND	t1.ITM_CD = m1.ITM_CD(+)
			AND	t1.ITM_SUB1 = m1.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m1.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m1.ITM_SUB3(+)
			AND	m1.DEL_FLG(+) = '0'
			AND	m1.RELEASE_FLG(+) = '1'
			AND	t1.BP_CD = m2.BP_CD(+)
			AND	m2.DEL_FLG(+) = '0'
			AND	t1.ITM_CD = m4.ITM_CD(+)
			AND	t1.ITM_SUB1 = m4.ITM_SUB1(+)
			AND	t1.ITM_SUB2 = m4.ITM_SUB2(+)
			AND	t1.ITM_SUB3 = m4.ITM_SUB3(+)
			AND	t1.SNO1 = m4.SNO1(+)
			AND	t1.SNO2 = m4.SNO2(+)
			AND	t1.SNO3 = m4.SNO3(+)
			AND	t1.SNO4 = m4.SNO4(+)
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_AC_OUT m
					WHERE	0=0
					AND	m.CALC_GRP_CD = t1.CALC_GRP_CD
					AND	m.AC_SLIP_TYP = C_AC_SLIP_DIFF_STD_ADJ
					AND	m.ITM_JNL_CD = m1.ITM_JNL_CD
					AND	m.ST_DT <= L_END_DT
					AND	m.END_DT >= L_END_DT
					)
			) x1
		GROUP BY x1.WG_CD, x1.MNG_DPT_CD,
			x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_NM,
			x1.ITM_JNL_CD, x1.AC_ITM_GRP_CD, x1.UNIT_CD,
			x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
			x1.AC_SLIP_TYP, x1.AC_RSN_CD,
			x1.LOC_CD, x1.STR_LN_CD, x1.BP_CD,
			x1.PO_NO, x1.SLO_NO, x1.IV_NO,
			x1.ASST_TYP,
			x1.REPURC_OBLI_FLG,
			x1.AREA_CD, x1.CNTRY_CD,
			x1.ITM_GRP_CD1, x1.ITM_GRP_CD2, x1.ITM_GRP_CD3, x1.ITM_GRP_CD4, x1.ITM_GRP_CD5,
			x1.ITM_GRP_CD6, x1.ITM_GRP_CD7, x1.ITM_GRP_CD8, x1.ITM_GRP_CD9, x1.ITM_GRP_CD10
		)
	LOOP
		IF x.QTY = 0 AND x.AMT = 0 OR x.AC_SLIP_TYP IS NULL THEN
			GOTO NEXT_LOOP ;
		END IF ;

		IF x.AC_RSN_CD IS NOT NULL AND INVALID_RSN_REC.EXISTS(x.AC_RSN_CD) THEN
			GOTO NEXT_LOOP ;
		END IF ;

		IF x.ITM_JNL_CD IS NULL THEN
			G_MSG := FCPA_ERR.MSG_BINDER(MAPA_COMM.F_TO_DISP_ITM(x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3, L_PARM)) ;
			FCPA_ERR.RAISE_APP_ERR('MGBXD0043', G_MSG) ;
		END IF ;

		L_SIGN := 1 ;

		L_PURC_DPT := NULL ;
		L_AP_DPT := NULL ;
		L_SLS_DPT := NULL ;
		L_AR_DPT := NULL ;
		L_GI_DPT := NULL ;
		L_GR_DPT := NULL ;
		L_BD_DPT := NULL ;
		L_SUB_DPT1 := NULL ;
		L_SUB_DPT2 := NULL ;
		L_SUB_DPT3 := NULL ;

		L_SPPL := NULL ;
		L_CST := NULL ;
		L_INV_COM := NULL ;

		L_AMT := 0 ;

		IF x.CNTRY_CD != L_CO.CNTRY_CD THEN
			L_FOREIGN := '1' ;
		ELSE
			L_FOREIGN := '0' ;
		END IF ;

		L_DPT1 := F_GET_AC_DPT(x.DPT_CD1, L_END_DT) ;

		IF x.DPT_CD2 = x.DPT_CD1 THEN
			L_DPT2 := L_DPT1 ;
		ELSE
			L_DPT2 := F_GET_AC_DPT(x.DPT_CD2, L_END_DT) ;
		END IF ;

		IF x.SLS_DPT_CD = x.DPT_CD1 THEN
			L_SLS_DPT := L_DPT1 ;
		ELSIF x.SLS_DPT_CD = x.DPT_CD2 THEN
			L_SLS_DPT := L_DPT2 ;
		ELSE
			L_SLS_DPT := F_GET_AC_DPT(x.SLS_DPT_CD, L_END_DT) ;
		END IF ;

		IF x.CALC_REC_TYP IN (
			C_CALC_REC_END_STK,
			C_CALC_REC_END_WIP,
			C_CALC_REC_ADJ,
			C_CALC_REC_COMP,
			C_CALC_REC_INST,
			C_CALC_REC_PURC
			)
		THEN
			L_GR_DPT := L_DPT1 ; --入庫部門：管理部門
			IF x.CALC_REC_TYP = C_CALC_REC_PURC THEN
				L_BD_DPT := L_DPT2 ; --負担部門：配賦部門
			ELSE
				L_BD_DPT := L_DPT1 ; --負担部門：管理部門
			END IF ;

			IF x.ASST_TYP = C_ASST_PROD OR x.CALC_REC_TYP = C_CALC_REC_PURC THEN
				L_SPPL := x.BP_CD ;
			ELSE
				L_CST := x.BP_CD ;
			END IF ;
			IF x.CALC_REC_TYP IN (C_CALC_REC_END_STK, C_CALC_REC_END_WIP) THEN
				L_INV_COM := x.STK_BP_CD ;
			END IF ;

		ELSIF x.CALC_REC_TYP = C_CALC_REC_INPT THEN
			IF x.AC_SLIP_TYP = C_AC_SLIP_BYPROD THEN
				L_SIGN := -1 ;
				L_GR_DPT := L_DPT1 ; --入庫部門：投入部門
				L_GI_DPT := L_DPT2 ; --出庫部門：製造部門
				L_BD_DPT := L_DPT2 ; --負担部門：製造部門
			ELSE
				L_GR_DPT := L_DPT2 ; --入庫部門：製造部門
				L_GI_DPT := L_DPT1 ; --出庫部門：投入部門
				L_BD_DPT := L_DPT2 ; --負担部門：製造部門
			END IF ;

			L_SPPL := x.BP_CD ;

		ELSIF x.CALC_REC_TYP = C_CALC_REC_SLS THEN
			L_GI_DPT := L_DPT1 ; --出庫部門：管理部門
			L_BD_DPT := L_DPT1 ; --負担部門：管理部門

			L_CST := x.BP_CD ;

		ELSIF x.CALC_REC_TYP = C_CALC_REC_IO THEN
			IF x.ASST_TYP = C_ASST_PROD THEN
				L_SPPL := NVL(x.STK_BP_CD, x.BP_CD) ;
			ELSE
				L_CST := NVL(x.STK_BP_CD, x.BP_CD) ;
			END IF ;

			IF x.COST_IO_TYP IN (C_COST_IO_FFR_PROV, C_COST_IO_ONR_PROV) THEN
				L_GI_DPT := L_DPT1 ; --出庫部門：管理部門
				L_GR_DPT := L_DPT2 ; --入庫部門：相手部門
				L_BD_DPT := L_DPT2 ; --負担部門：相手部門

			ELSIF x.COST_IO_TYP = C_COST_IO_STK_IN THEN

				IF x.TRD_GRP IS NOT NULL
				AND (
					L_PROD_ITM_DIFF_FLG = '1' AND x.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_GR
					OR
					L_PROD_ITM_RET_DIFF_FLG = '1' AND x.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_RET_GR
					OR
					L_DPT_XFR_DIFF_FLG = '1' AND x.AC_SLIP_TYP = C_AC_SLIP_DPT_XFR_GR
				) THEN
					FOR m IN (
						SELECT	NVL(SUM(t.AMT), 0) AMT
						FROM	MGT_ACC_TRD t
						WHERE	0=0
						AND	t.CALC_NO = I_CALC_NO
						AND	t.CALC_GRP_CD = I_CALC_GRP_CD
						AND	t.TRD_GRP = x.TRD_GRP
						)
					LOOP
						IF m.AMT = 0 THEN
							IF (
								L_PROD_ITM_FLG = '1' AND x.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_GR
								OR
								L_PROD_ITM_RET_FLG = '1' AND x.AC_SLIP_TYP = C_AC_SLIP_PROD_ITM_RET_GR
								OR
								L_DPT_XFR_FLG = '1' AND x.AC_SLIP_TYP = C_AC_SLIP_DPT_XFR_GR
							) THEN
								NULL ;
							ELSE
								GOTO NEXT_LOOP ;
							END IF ;
						ELSE
							L_AMT := m.AMT * -1 ;
						END IF ;
					END LOOP ;
				END IF ;

				L_GI_DPT := L_DPT2 ; --出庫部門：相手部門
				L_GR_DPT := L_DPT1 ; --入庫部門：管理部門
				L_BD_DPT := L_DPT1 ; --負担部門：管理部門

			ELSIF x.COST_IO_TYP IN (C_COST_IO_STK_OUT, C_COST_IO_STK_IO) THEN
				L_GI_DPT := L_DPT1 ; --出庫部門：管理部門
				L_GR_DPT := L_DPT2 ; --入庫部門：相手部門
				L_BD_DPT := L_DPT2 ; --負担部門：相手部門
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;

			IF x.COST_IO_TYP = C_COST_IO_STK_OUT
			AND (x.AC_SLIP_TYP = C_AC_SLIP_IN_STKTK AND L_REV_IN_STKTK_FLG = G_ON
			  OR x.AC_SLIP_TYP = C_AC_SLIP_OTH_CCN_GR AND L_REV_OTH_CCN_GR_FLG = G_ON
			  )
			THEN
				L_SIGN := -1 ;
			END IF ;

		ELSIF x.AC_SLIP_TYP IN (C_AC_SLIP_EOM_STK_ASM_MIS, C_AC_SLIP_STK_ASM_DIFF) THEN
			L_GI_DPT := L_DPT1 ; --出庫部門：管理部門
			L_GR_DPT := L_DPT1 ; --入庫部門：管理部門
			L_BD_DPT := L_DPT1 ; --負担部門：管理部門

			L_SPPL := x.BP_CD ;

		ELSIF x.AC_SLIP_TYP IN (C_AC_SLIP_ITM_ALC) THEN
			L_GI_DPT := L_DPT1 ; --出庫部門：費用部門
			L_GR_DPT := L_DPT2 ; --入庫部門：管理部門
			L_BD_DPT := L_DPT2 ; --負担部門：管理部門

			L_SPPL := x.BP_CD ;

		ELSIF x.AC_SLIP_TYP IN (C_AC_SLIP_DIFF_IO_SUM, C_AC_SLIP_DIFF_IO_PRI, C_AC_SLIP_DIFF_IO_RATE) THEN
			L_GR_DPT := L_DPT1 ; --入庫部門：管理部門
			L_BD_DPT := L_DPT2 ; --負担部門：配賦部門

			L_SPPL := x.BP_CD ;

		ELSIF x.AC_SLIP_TYP IN (C_AC_SLIP_DIFF_QT_PAR, C_AC_SLIP_DIFF_PR_PAR, C_AC_SLIP_DIFF_WK,
				C_AC_SLIP_DIFF_ACT1, C_AC_SLIP_DIFF_ACT2, C_AC_SLIP_DIFF_ACT3, C_AC_SLIP_DIFF_ACT4, C_AC_SLIP_DIFF_ACT5,
				C_AC_SLIP_DIFF_RATE_ITM, C_AC_SLIP_DIFF_OUTSRC_SUM, C_AC_SLIP_DIFF_OUTSRC_PRI, C_AC_SLIP_DIFF_OUTSRC_RATE,
				C_AC_SLIP_DIFF_SS_PAR, C_AC_SLIP_DIFF_STD_ADJ) THEN
			L_GR_DPT := L_DPT1 ; --入庫部門：管理部門
			L_BD_DPT := L_DPT1 ; --負担部門：管理部門

			L_SPPL := x.BP_CD ;

		ELSIF x.AC_SLIP_TYP IN (C_AC_SLIP_DIFF_QT_CHD, C_AC_SLIP_DIFF_PR_CHD, C_AC_SLIP_DIFF_SS_CHD) THEN
			L_GI_DPT := L_DPT2 ; --出庫部門：管理部門
			L_GR_DPT := L_DPT1 ; --入庫部門：管理部門
			L_BD_DPT := L_DPT1 ; --負担部門：管理部門

			L_SPPL := x.BP_CD ;

		ELSIF x.AC_SLIP_TYP IN (C_AC_SLIP_DIFF_RATE_ALC) THEN
			L_GI_DPT := L_DPT1 ; --出庫部門：費用部門
			L_BD_DPT := L_DPT1 ; --負担部門：費用部門

			L_SPPL := x.BP_CD ;

		ELSE
			GOTO NEXT_LOOP ;

		END IF ;

		i := i + 1 ;

		rec(i).DATA_NO		:= LPAD(MAPA_NUM.F_GET_SEQ(C_AC_COST_SEQ), C_IT_DAT_NO_L, '0') ;
		rec(i).WG_CD	:= x.WG_CD ;
		rec(i).AC_YM	:= I_YM ;
		rec(i).CALC_GRP_CD	:= I_CALC_GRP_CD ;
		rec(i).CALC_NO		:= I_CALC_NO ;
		rec(i).AC_DT		:= L_END_DT ;
		rec(i).AC_SLIP_TYP	:= x.AC_SLIP_TYP ;
		rec(i).AC_RSN_CD	:= x.AC_RSN_CD ;
		rec(i).PURC_DPT_CD	:= L_PURC_DPT ;
		rec(i).AP_DPT_CD	:= L_AP_DPT ;
		rec(i).SLS_DPT_CD	:= L_SLS_DPT ;
		rec(i).AR_DPT_CD	:= L_AR_DPT ;
		rec(i).GI_DPT_CD	:= L_GI_DPT ;
		rec(i).GR_DPT_CD	:= L_GR_DPT ;
		rec(i).BD_DPT_CD	:= L_BD_DPT ;
		rec(i).SUB_DPT_CD1	:= L_SUB_DPT1 ;
		rec(i).SUB_DPT_CD2	:= L_SUB_DPT2 ;
		rec(i).SUB_DPT_CD3	:= L_SUB_DPT3 ;
