		rec(i).BASE_UNIT_CD	:= x.UNIT_CD ;
		rec(i).BASE_UNIT_QTY	:= x.QTY * L_SIGN ;
		rec(i).BASE_CUR_CD	:= L_CO.BASE_CUR_CD ;
		rec(i).AMT		:= x.AMT * L_SIGN ;
		rec(i).SPPL_CD		:= L_SPPL ;
		rec(i).CST_CD		:= L_CST ;
		rec(i).INV_COM_CD	:= L_INV_COM ;
		IF x.AREA_CD IS NOT NULL THEN
			rec(i).AREA_CD := x.AREA_CD ;
		ELSIF L_INV_COM IS NULL THEN
			rec(i).AREA_CD := L_CO.AREA_CD ;
		END IF ;

		IF x.CNTRY_CD IS NOT NULL THEN
			rec(i).CNTRY_CD	:= x.CNTRY_CD ;
		ELSIF L_INV_COM IS NULL THEN
			rec(i).CNTRY_CD	:= L_CO.CNTRY_CD ;
		END IF ;
		rec(i).FOREIGN_FLG	:= L_FOREIGN ;
		rec(i).USR_CD		:= x.USR_CD ;
		rec(i).TRD_GRP		:= x.TRD_GRP ;
		rec(i).TRD_AC_ITM_GRP_CD := x.TRD_AC_ITM_GRP_CD ;
		rec(i).TRD_ITM_JNL_CD	:= x.TRD_ITM_JNL_CD ;
		rec(i).TRD_ITM_CD	:= x.TRD_ITM_CD ;
		rec(i).TRD_ITM_SUB1	:= x.TRD_ITM_SUB1 ;
		rec(i).TRD_ITM_SUB2	:= x.TRD_ITM_SUB2 ;
		rec(i).TRD_ITM_SUB3	:= x.TRD_ITM_SUB3 ;
