				rec(i).DATA_NO := LPAD(MAPA_NUM.F_GET_SEQ(C_AC_COST_SEQ), C_IT_DAT_NO_L, '0') ;
				rec(i).AC_SLIP_TYP := C_AC_SLIP_PROD_ITM_RET_DIFF ;
				rec(i).AMT := L_AMT ;
