					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD6 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD6) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD7 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD7) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD8 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD8) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD9 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD9) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD10 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD10) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR1 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR2 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR3 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR4 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR4 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR5 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR5 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR6 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR6 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR7 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR7 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR8 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR8 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR9 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR9 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR10 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR10 ;
					C_NOT_NULL_FLG := G_OFF ;
				ELSE
					C_JNL_KEY_SET_VAL := NULL ;
					C_NOT_NULL_FLG := G_OFF ;
			END CASE ;

			-- NULL可項目がNULLの場合、NULL不可項目がNULL文字の場合
			IF (C_JNL_KEY_SET_VAL IS NULL AND C_NOT_NULL_FLG = G_OFF)
				OR (C_JNL_KEY_SET_VAL = G_NULL_VAL AND C_NOT_NULL_FLG = G_ON) THEN
				C_JNL_KEY_SET_VAL := C_JNL_KEY_MAP.DEFAULT_CD ;
			END IF ;

			CASE C_JNL_KEY_COL_TYP
				WHEN C_JNL_KEY1 THEN
					rec(i).JNL_KEY1 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY1_L) ;
				WHEN C_JNL_KEY2 THEN
					rec(i).JNL_KEY2 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY2_L) ;
				WHEN C_JNL_KEY3 THEN
					rec(i).JNL_KEY3 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY3_L) ;
				WHEN C_JNL_KEY4 THEN
					rec(i).JNL_KEY4 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY4_L) ;
				WHEN C_JNL_KEY5 THEN
					rec(i).JNL_KEY5 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY5_L) ;
				WHEN C_JNL_KEY6 THEN
					rec(i).JNL_KEY6 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY6_L) ;
				WHEN C_JNL_KEY7 THEN
					rec(i).JNL_KEY7 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY7_L) ;
				WHEN C_JNL_KEY8 THEN
					rec(i).JNL_KEY8 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY8_L) ;
				WHEN C_JNL_KEY9 THEN
					rec(i).JNL_KEY9 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY9_L) ;
				WHEN C_JNL_KEY10 THEN
					rec(i).JNL_KEY10 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY10_L) ;
			END CASE ;
		END LOOP ;

		IF i > C_MAX_CNT THEN
			P_AC_COST_INSERT() ;
		END IF ;

		<<NEXT_LOOP>>
			NULL ;

	END LOOP ;

	P_AC_COST_INSERT() ;

	SELECT COUNT(*) INTO L_CNT FROM MAM_COST_SLIP_JNL
	WHERE CALC_GRP_CD = I_CALC_GRP_CD
	AND AC_SLIP_TYP = C_AC_SLIP_DPT_ALC ;

	IF L_CNT = 0 THEN
		GOTO SKIP_DPT_ALC ;
	END IF ;

	-- 部門間配賦の結果を送信
	rec.DELETE ;
	i := 0 ;
	FOR x IN (
		SELECT
			Z.LVL,
			Z.SRC_DPT_CD,
			Z.DPT_CD,
			Z.SRC_ALC_AC_CD,
			Z.ALC_AC_CD,
			Z.WG_CD,
			Z.LOC_CD,
			ITM.AC_ITM_GRP_CD,
			NVL(ITM.ITM_JNL_CD, G_NULL_VAL) ITM_JNL_CD,
			NVL(Z.ITM_CD, G_NULL_VAL) ITM_CD,
			NVL(Z.ITM_SUB1, G_NULL_VAL) ITM_SUB1,
			NVL(Z.ITM_SUB2, G_NULL_VAL) ITM_SUB2,
			NVL(Z.ITM_SUB3, G_NULL_VAL) ITM_SUB3,
			NVL(SUN.ITM_NM, ITM.ITM_NM) ITM_NM,
			NVL(Z.LOT_NO, G_NULL_VAL) LOT_NO,
			NVL(Z.SUBLOT_NO, G_NULL_VAL) SUBLOT_NO,
			NVL(Z.SNO1, G_NULL_VAL) SNO1,
			NVL(Z.SNO2, G_NULL_VAL) SNO2,
			NVL(Z.SNO3, G_NULL_VAL) SNO3,
			NVL(Z.SNO4, G_NULL_VAL) SNO4,
			Z.SLO_NO,
			Z.PO_NO,
			Z.IV_NO,
			ITM.UNIT_CD,
			Z.AMT,
			ITM.ITM_GRP_CD1,
			ITM.ITM_GRP_CD2,
			ITM.ITM_GRP_CD3,
			ITM.ITM_GRP_CD4,
			ITM.ITM_GRP_CD5,
			ITM.ITM_GRP_CD6,
			ITM.ITM_GRP_CD7,
			ITM.ITM_GRP_CD8,
			ITM.ITM_GRP_CD9,
			ITM.ITM_GRP_CD10,
			NULL	TRD_ITM_GRP_CD1,
			NULL	TRD_ITM_GRP_CD2,
			NULL	TRD_ITM_GRP_CD3,
			NULL	TRD_ITM_GRP_CD4,
			NULL	TRD_ITM_GRP_CD5,
			NULL	TRD_ITM_GRP_CD6,
			NULL	TRD_ITM_GRP_CD7,
			NULL	TRD_ITM_GRP_CD8,
			NULL	TRD_ITM_GRP_CD9,
			NULL	TRD_ITM_GRP_CD10
		FROM (
			SELECT
				ROWNUM				NO,
				LEVEL				LVL,
				PRIOR T.DPT_CD		SRC_DPT_CD,
				PRIOR T.ALC_AC_CD	SRC_ALC_AC_CD,
				T.DPT_CD,
				T.ALC_AC_CD,
				T.WG_CD,
				T.LOC_CD,
				T.ITM_CD,
				T.ITM_SUB1,
				T.ITM_SUB2,
				T.ITM_SUB3,
				T.LOT_NO,
				T.SUBLOT_NO,
				T.SNO1,
				T.SNO2,
				T.SNO3,
				T.SNO4,
				T.SLO_NO,
				T.PO_NO,
				T.IV_NO,
				T.AMT
			FROM
				MGT_PRE_ALC_PATH T
			WHERE 0=0
			START WITH T.CALC_NO = I_CALC_NO
				AND T.CALC_GRP_CD = I_CALC_GRP_CD
				AND T.DPT_CD IS NOT NULL
				AND T.PRE_ALC_LVL = 0
				AND (
					EXISTS (
						SELECT 'X' FROM MAM_COST_AC_DPT_MAP W
						WHERE W.DPT_CD = T.DPT_CD
						AND W.ST_DT <= L_END_DT
						AND W.END_DT >= L_END_DT
						AND EXISTS (
							SELECT 'X' FROM MAM_AC_DPT Y
							WHERE Y.AC_DPT_CD = W.AC_DPT_CD
							AND Y.ST_DT <= L_END_DT
							AND Y.END_DT >= L_END_DT
						)
					)
					OR
					EXISTS (
							SELECT 'X' FROM MAM_AC_DPT Y
							WHERE Y.AC_DPT_CD = T.DPT_CD
							AND Y.ST_DT <= L_END_DT
							AND Y.END_DT >= L_END_DT
					)
				)
				AND NOT EXISTS (
					SELECT 'X' FROM MAM_ITM_SRCH W
					WHERE W.ITM_CD = T.ITM_CD
					AND W.ITM_SUB1 = T.ITM_SUB1
					AND W.ITM_SUB2 = T.ITM_SUB2
					AND W.ITM_SUB3 = T.ITM_SUB3
					AND W.DEL_FLG = '0'
					AND W.RELEASE_FLG = '1'
					AND EXISTS (
						SELECT 'X' FROM MAM_COST_AC_OUT Y
						WHERE	0=0
						AND Y.CALC_GRP_CD = I_CALC_GRP_CD
						AND Y.AC_SLIP_TYP = C_AC_SLIP_DPT_ALC
						AND Y.ITM_JNL_CD = W.ITM_JNL_CD
						AND Y.ST_DT <= L_END_DT
						AND Y.END_DT >= L_END_DT
					)
				)
			CONNECT BY PRIOR T.PRE_ALC_SEQ = T.SRC_PRE_ALC_SEQ
				AND PRIOR T.CALC_NO = T.CALC_NO
				AND PRIOR T.CALC_GRP_CD = T.CALC_GRP_CD
				AND NOT EXISTS (
					SELECT 'X' FROM MGT_PRE_ALC_PATH W
					WHERE W.CALC_NO = T.CALC_NO
					AND W.CALC_GRP_CD = T.CALC_GRP_CD
					AND W.SRC_PRE_ALC_SEQ = T.SRC_PRE_ALC_SEQ
					AND W.DPT_CD IS NULL)
			) Z,
			MAM_ITM_SRCH	ITM,
			MAM_SUNDRY_ITM	SUN
		WHERE 0=0
		AND Z.LVL <> 1
		AND ITM.ITM_CD(+) = Z.ITM_CD
		AND ITM.ITM_SUB1(+) = Z.ITM_SUB1
		AND ITM.ITM_SUB2(+) = Z.ITM_SUB2
		AND ITM.ITM_SUB3(+) = Z.ITM_SUB3
		AND ITM.DEL_FLG(+) = '0'
		AND ITM.RELEASE_FLG(+) = '1'
		AND SUN.ITM_CD(+) = Z.ITM_CD
		AND SUN.ITM_SUB1(+) = Z.ITM_SUB1
		AND SUN.ITM_SUB2(+) = Z.ITM_SUB2
		AND SUN.ITM_SUB3(+) = Z.ITM_SUB3
		AND SUN.SNO1(+) = Z.SNO1
		AND SUN.SNO2(+) = Z.SNO2
		AND SUN.SNO3(+) = Z.SNO3
		AND SUN.SNO4(+) = Z.SNO4
		ORDER BY Z.NO
		)
	LOOP

		L_GI_DPT := F_GET_AC_DPT(x.SRC_DPT_CD, L_END_DT, '1') ;
		L_GR_DPT := F_GET_AC_DPT(x.DPT_CD, L_END_DT, '1') ;

		IF L_GI_DPT IS NULL THEN
			L_GI_DPT := dpt_path(x.LVL-1) ;
		END IF ;
		dpt_path(x.LVL) := L_GI_DPT ;

		IF L_GR_DPT IS NULL THEN
			GOTO NEXT_LOOP ;
		END IF ;

		i := i + 1 ;

		rec(i).WG_CD			:= x.WG_CD ;
		rec(i).AC_YM			:= I_YM ;
		rec(i).CALC_GRP_CD		:= I_CALC_GRP_CD ;
		rec(i).CALC_NO			:= I_CALC_NO ;
		rec(i).AC_DT			:= L_END_DT ;
		rec(i).AC_SLIP_TYP		:= C_AC_SLIP_DPT_ALC ;
		rec(i).GI_DPT_CD		:= L_GI_DPT ;
		rec(i).GR_DPT_CD		:= L_GR_DPT ;
		rec(i).BD_DPT_CD		:= L_GR_DPT ;
		rec(i).LOC_CD			:= x.LOC_CD ;
		rec(i).AC_ITM_GRP_CD	:= x.AC_ITM_GRP_CD ;
		rec(i).ITM_JNL_CD		:= x.ITM_JNL_CD ;
		rec(i).ITM_CD			:= x.ITM_CD ;
		rec(i).ITM_SUB1			:= x.ITM_SUB1 ;
		rec(i).ITM_SUB2			:= x.ITM_SUB2 ;
		rec(i).ITM_SUB3			:= x.ITM_SUB3 ;
		rec(i).ITM_NM			:= x.ITM_NM ;
		rec(i).LOT_NO			:= x.LOT_NO ;
		rec(i).SUBLOT_NO		:= x.SUBLOT_NO ;
		rec(i).SNO1				:= x.SNO1 ;
		rec(i).SNO2				:= x.SNO2 ;
		rec(i).SNO3				:= x.SNO3 ;
		rec(i).SNO4				:= x.SNO4 ;
		rec(i).SLO_NO			:= x.SLO_NO ;
		rec(i).PO_NO			:= x.PO_NO ;
		rec(i).IV_NO			:= x.IV_NO ;
		rec(i).BASE_UNIT_CD		:= x.UNIT_CD ;
		rec(i).BASE_UNIT_QTY	:= 0 ;
		rec(i).BASE_CUR_CD		:= L_CO.BASE_CUR_CD ;
		rec(i).AMT				:= x.AMT ;
		rec(i).FOREIGN_FLG		:= '0' ;
		rec(i).JNL_FIN_CNT		:= 0 ;
		rec(i).SRC_ALC_AC_CD	:= x.SRC_ALC_AC_CD ;
		rec(i).ALC_AC_CD		:= x.ALC_AC_CD ;

		FOR j IN 1..10 LOOP
			CASE j
				WHEN 1 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY1 ;
				WHEN 2 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY2 ;
				WHEN 3 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY3 ;
				WHEN 4 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY4 ;
				WHEN 5 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY5 ;
				WHEN 6 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY6 ;
				WHEN 7 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY7 ;
				WHEN 8 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY8 ;
				WHEN 9 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY9 ;
				WHEN 10 THEN
					C_JNL_KEY_COL_TYP := C_JNL_KEY10 ;
			END CASE ;

			-- 仕訳キー対応マスタのレコードを取得
			C_JNL_KEY_MAP := NULL ;
			P_GET_JNL_KEY_MAP(rec(i).AC_SLIP_TYP, C_JNL_KEY_COL_TYP, C_JNL_KEY_MAP) ;

			IF C_JNL_KEY_MAP.JNL_KEY_SET_COL_TYP IS NULL THEN
				CONTINUE ;
			END IF ;

			-- 取引先を専用レコードへ格納
			C_BP_REC := NULL ;
			C_BP_REC.CST_CD := rec(i).CST_CD ;
			C_BP_REC.SPPL_CD := rec(i).SPPL_CD ;
			C_BP_REC.INV_COM_CD := rec(i).INV_COM_CD ;

			-- 仕訳キー設定項目に対応するカラムの値を取得
			CASE C_JNL_KEY_MAP.JNL_KEY_SET_COL_TYP
				WHEN C_WG_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).WG_CD ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_PURC_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).PURC_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_AP_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).AP_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SLS_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).SLS_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_AR_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).AR_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_GI_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).GI_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_GR_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).GR_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BD_DPT_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).BD_DPT_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_DPT_CD1 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_DPT_CD1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_DPT_CD2 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_DPT_CD2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_DPT_CD3 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_DPT_CD3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_LOC_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).LOC_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_STR_LN_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).STR_LN_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_CST_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).CST_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SPPL_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).SPPL_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_INV_COM_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).INV_COM_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_AC_ITM_GRP_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).AC_ITM_GRP_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).ITM_CD ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_ITM_SUB1 THEN
					C_JNL_KEY_SET_VAL := rec(i).ITM_SUB1 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_ITM_SUB2 THEN
					C_JNL_KEY_SET_VAL := rec(i).ITM_SUB2 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_ITM_SUB3 THEN
					C_JNL_KEY_SET_VAL := rec(i).ITM_SUB3 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_SNO1 THEN
					C_JNL_KEY_SET_VAL := rec(i).SNO1 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_SNO2 THEN
					C_JNL_KEY_SET_VAL := rec(i).SNO2 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_SNO3 THEN
					C_JNL_KEY_SET_VAL := rec(i).SNO3 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_SNO4 THEN
					C_JNL_KEY_SET_VAL := rec(i).SNO4 ;
					C_NOT_NULL_FLG := G_ON ;
				WHEN C_ITM_GRP_CD1 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD2 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD3 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD4 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD4 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD5 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD5 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD6 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD6 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD7 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD7 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD8 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD8 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD9 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD9 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ITM_GRP_CD10 THEN
					C_JNL_KEY_SET_VAL := x.ITM_GRP_CD10 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_AC_ITM_GRP_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_AC_ITM_GRP_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_JNL_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_ITM_JNL_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_ITM_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_SUB1 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_ITM_SUB1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_SUB2 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_ITM_SUB2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_SUB3 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_ITM_SUB3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_SNO1 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_SNO1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_SNO2 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_SNO2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_SNO3 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_SNO3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_SNO4 THEN
					C_JNL_KEY_SET_VAL := rec(i).TRD_SNO4 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD1 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD2 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD3 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD4 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD4 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD5 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD5 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD6 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD6 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD7 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD7 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD8 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD8 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD9 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD9 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_TRD_ITM_GRP_CD10 THEN
					C_JNL_KEY_SET_VAL := x.TRD_ITM_GRP_CD10 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_AREA_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).AREA_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_CNTRY_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).CNTRY_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_ALC_AC_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).ALC_AC_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SRC_ALC_AC_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).SRC_ALC_AC_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_EXPNS_CD THEN
					C_JNL_KEY_SET_VAL := rec(i).EXPNS_CD ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD1 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD1) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD2 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD2) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD3 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD3) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD4 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD4) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD5 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD5) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD6 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD6) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD7 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD7) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD8 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD8) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD9 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD9) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_BP_GRP_CD10 THEN
					C_JNL_KEY_SET_VAL := F_GET_BP_GRP(C_BP_REC, C_JNL_KEY_MAP, C_BP_GRP_CD10) ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR1 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR1 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR2 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR2 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR3 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR3 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR4 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR4 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR5 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR5 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR6 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR6 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR7 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR7 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR8 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR8 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR9 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR9 ;
					C_NOT_NULL_FLG := G_OFF ;
				WHEN C_SUB_CHAR10 THEN
					C_JNL_KEY_SET_VAL := rec(i).SUB_CHAR10 ;
					C_NOT_NULL_FLG := G_OFF ;
				ELSE
					C_JNL_KEY_SET_VAL := NULL ;
					C_NOT_NULL_FLG := G_OFF ;
			END CASE ;

			-- NULL可項目がNULLの場合、NULL不可項目がNULL文字の場合
			IF (C_JNL_KEY_SET_VAL IS NULL AND C_NOT_NULL_FLG = G_OFF)
				OR (C_JNL_KEY_SET_VAL = G_NULL_VAL AND C_NOT_NULL_FLG = G_ON) THEN
				C_JNL_KEY_SET_VAL := C_JNL_KEY_MAP.DEFAULT_CD ;
			END IF ;

			CASE C_JNL_KEY_COL_TYP
				WHEN C_JNL_KEY1 THEN
					rec(i).JNL_KEY1 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY1_L) ;
				WHEN C_JNL_KEY2 THEN
					rec(i).JNL_KEY2 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY2_L) ;
				WHEN C_JNL_KEY3 THEN
					rec(i).JNL_KEY3 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY3_L) ;
				WHEN C_JNL_KEY4 THEN
					rec(i).JNL_KEY4 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY4_L) ;
				WHEN C_JNL_KEY5 THEN
					rec(i).JNL_KEY5 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY5_L) ;
				WHEN C_JNL_KEY6 THEN
					rec(i).JNL_KEY6 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY6_L) ;
				WHEN C_JNL_KEY7 THEN
					rec(i).JNL_KEY7 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY7_L) ;
				WHEN C_JNL_KEY8 THEN
					rec(i).JNL_KEY8 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY8_L) ;
				WHEN C_JNL_KEY9 THEN
					rec(i).JNL_KEY9 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY9_L) ;
				WHEN C_JNL_KEY10 THEN
					rec(i).JNL_KEY10 := SUBSTR(C_JNL_KEY_SET_VAL, 1, MAPA_META.JNL_KEY10_L) ;
			END CASE ;
		END LOOP ;

		IF i > C_MAX_CNT THEN
			P_AC_COST_MERGE() ;
		END IF ;

		<<NEXT_LOOP>>
			NULL ;

	END LOOP ;

	P_AC_COST_MERGE() ;

	<<SKIP_DPT_ALC>>

	SELECT COUNT(*) INTO sum_i FROM MBT_AC_COST t
	WHERE 0=0
	AND t.CALC_GRP_CD = I_CALC_GRP_CD
	AND t.AC_YM = I_YM ;

	JNL_KEY_MAP_REC.DELETE ;
	BP_GRP_REC.DELETE ;
	DPT_MAP_REC.DELETE ;
	INVALID_RSN_REC.DELETE ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBDD0015', sum_i) ;

END P_SEND_MAIN ;

PROCEDURE P_SEND (
	I_CALC_GRP_CD	IN MAPA_META.CALC_GRP_CD%TYPE,
	I_YM		IN MAPA_META.YM%TYPE
)
/**************************************************************************
<SYNOPSIS>
	会計ＩＦの送信処理
<REMARKS>

<ARGUMENTS>
<IN>	I_CALC_GRP_CD
		計算グループＣＤ
<IN>	I_YM
		年月
<HISTORY>
**************************************************************************/
IS
	L_CALC_NO	MAPA_META.CALC_NO%TYPE ;
	L_CNT		NUMBER ;
BEGIN
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0030', I_CALC_GRP_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M), NULL) ;

	-- 確定情報のロック
	MGPA_CALC_FIX.P_LOCK(I_CALC_GRP_CD, I_YM) ;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MGT_CALC_FIX t
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.YM = I_YM
	AND	t.AC_IF_FLG = '0'
	;

	IF L_CNT = 0 THEN
		RETURN ;
	END IF ;

	SELECT	MAX(t.CALC_NO)
	INTO	L_CALC_NO
	FROM	MGT_CALC_FIX t
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.YM = I_YM
	AND	t.AC_IF_FLG = '0'
	;

	IF L_CALC_NO IS NULL THEN
		RETURN ;
	END IF ;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MAM_COST_SLIP_JNL m
	WHERE	0=0
	AND	m.CALC_GRP_CD = I_CALC_GRP_CD
	;

	IF L_CNT = 0 THEN
		G_MSG := FCPA_ERR.MSG_BINDER(I_CALC_GRP_CD) ;
		FCPA_ERR.RAISE_APP_ERR('MGBDD0014', G_MSG) ;
	END IF ;

	P_SEND_MAIN(I_CALC_GRP_CD, L_CALC_NO, I_YM) ;

	UPDATE	MGT_CALC_FIX t
	SET	t.AC_IF_FLG = '1'
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.YM = I_YM
	;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_AC_IF.P_SEND') ;

END P_SEND ;

PROCEDURE P_CANCEL (
	I_CALC_GRP_CD	IN MAPA_META.CALC_GRP_CD%TYPE,
	I_YM		IN MAPA_META.YM%TYPE
)
/**************************************************************************
<SYNOPSIS>
	会計ＩＦの送信取消処理
<REMARKS>

<ARGUMENTS>
<IN>	I_CALC_GRP_CD
		計算グループＣＤ
<IN>	I_YM
		年月
<HISTORY>
**************************************************************************/
IS
	L_CNT	NUMBER ;
BEGIN
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0030', I_CALC_GRP_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M), NULL) ;

	-- 確定情報のロック
	MGPA_CALC_FIX.P_LOCK(I_CALC_GRP_CD, I_YM) ;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MGT_CALC_FIX t
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.YM = I_YM
	AND	t.AC_IF_FLG = '1'
	;

	IF L_CNT = 0 THEN
		RETURN ;
	END IF ;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MBT_AC_COST t
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.AC_YM = I_YM
	AND	t.JNL_FIN_CNT > 0
	;

	IF L_CNT > 0 THEN
		G_MSG := FCPA_ERR.MSG_BINDER(I_CALC_GRP_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M)) ;
		FCPA_ERR.RAISE_APP_ERR('MGBDD0013', G_MSG) ;
	END IF ;

	DELETE	MBT_AC_COST t
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.AC_YM = I_YM
	;

	UPDATE	MGT_CALC_FIX t
	SET	t.AC_IF_FLG = '0'
	WHERE	0=0
	AND	t.CALC_GRP_CD = I_CALC_GRP_CD
	AND	t.YM = I_YM
	;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_AC_IF.P_CANCEL') ;

END P_CANCEL ;

END MGPA_AC_IF ;

/
show errors;


